/* Evolvlings: path conversations of era 7, Los Vientos Vendidos (the ten eras plan, https://claude.ai/artifact/RFy6uGdhz9DJeW7e9ZfdkE).
   Same format as the zone files (see rpg/events-aurora.js). These events only come up while the Glade lives in era 7:
   need.era says so (lore.js needOk), and need.layer counts the guardians beaten since the era began.
   Another generation has passed since La Corte de los Nombres. How era 6 ended (m6_velo / m6_nombres / m6_guardado)
   is still in the flags and changes a few lines and options.
   The wind that rises from the depths of the Glade carries the Root's dreams, and a song sung on it sticks in every
   head. The Choir of Three is back as a business: its windmills on the summit catch the wind and sell songs.
   The nine peoples you bring together set the u7_* flags; with all nine, the final dilemma offers The Hand Song
   (rpg/data-eras.js derives e7_nueve). The m7_* flags are the marks this era leaves on the next.
   Loaded after the zone files (it adds to them). English text: rpg/events-era7.en.js. */
window.EVEVENTS = window.EVEVENTS || {};
(function (E) {
  const add = (zone, evs) => { E[zone] = Object.assign(E[zone] || {}, evs); };

  /* ==================== Entrega 1: los molinos, el Coro, Brisa, Arpegia, la canción del Vado, el verso vendido y el final ==================== */

  /* ---------- Los Altos: los molinos, Brisa, Arpegia, el Coro de los Tres, la canción del Vado y el verso vendido ---------- */
  add("heights", {
    "e7-molinos": { kind: "encuentro", need: { era: 7, layer: 1 }, first: true, who: { aspa: "Aspa, molinera del Coro" }, start: "a", nodes: {
      a: { say: [[null, "En la cumbre de los Altos giran doce molinos de madera, altos como árboles. Sus aspas no muelen trigo: atrapan el viento que sube del fondo del Claro, un viento tibio que huele a tierra mojada."],
                 ["aspa", "Aspa, molinera del Coro. Los hice yo, con mis hermanos. El viento entra por las aspas, el Coro le canta adentro, y la canción sale por el otro lado hacia todo el Claro. Y se pega. Todos la cantan."],
                 ["aspa", "Por primera vez en cien años, los Altos tienen plata. No bajamos a pedir. Nos vienen a comprar. ¿Sabe lo que es eso para una cumbre que siempre tocó «nos falta»?"]],
           opts: [{ t: "«¿Qué tiene ese viento?»", go: "viento", once: true },
                  { t: "Romper los molinos", go: "romper" },
                  { t: "«Que sean de toda la cumbre, no solo del Coro.»", go: "cumbre" },
                  { t: "Ponerles una canción tuya", go: "tuya" },
                  { t: "Dejarlos como están", go: "dejar" }] },
      viento: { say: [["aspa", "Sueños. Eso dicen los del Fondo. Que sube desde la Raíz, lleno de lo que la Raíz sueña. Yo no sé. Sé que una canción cantada en él no se olvida."],
                      ["aspa", "Dicen que lo descubrió Brisa, la voz del Coro, cuando era niña, cantando una tontería sobre una cabra con sombrero. Todavía hay viejos que la tararean sin querer."]], back: "a" },
      romper: { say: [[null, "Esa noche subes con un hacha al molino más grande. Cortas las cuerdas de las aspas. El molino gira loco un rato, cruje, y se detiene."],
                      [null, "Aspa llega corriendo, en camisón. Mira el molino roto. No grita. Se sienta en la nieve."],
                      ["aspa", "Uno. Quedan once. Mañana lo arreglo. Pero ahora sé que alguien puede subir con un hacha. Eso no se arregla."]], end: { xp: 16, flag: "m7_molinosRotos" } },
      cumbre: { say: [["aspa", "¿De toda la cumbre? ¿Los pastores, los tamboreros, las viejas que tejen?"],
                      [null, "Lo piensa. Esa semana reúne a los cinco pueblos de los Altos en la plaza. Votan. Los molinos pasan a ser de todos: cada pueblo canta en uno, por turnos, y la plata se reparte."],
                      ["aspa", "El Coro me va a odiar. Pero los Altos van a comer parejo. Eso no lo había hecho nadie con el viento."]], end: { xp: 20, flag: ["m7_molinosCumbre", "u7_altos"] } },
      tuya: { say: [[null, "Le pides a Aspa que deje un molino libre una noche. Te paras frente a las aspas y cantas algo tuyo, lo primero que te sale."],
                    [null, "Al día siguiente, en el Prado, en las Cuevas, en el Lago, la gente tararea tu canción sin saber de dónde salió."],
                    ["aspa", "Ahora usted también vende. Sin cobrar, pero vende. ¿Qué canción era? La tengo en la cabeza y no sé qué dice."]], end: { xp: 14, flag: "m7_molinosTuyos" } },
      dejar: { say: [["aspa", "Como están. Bien. Mañana el Coro estrena canción. Va a sonar en todo el Claro antes del mediodía."],
                     [null, "Al día siguiente, todo el Claro canta lo mismo. Tú también, sin darte cuenta, mientras caminas de vuelta."]], end: { xp: 8, flag: "m7_molinosQuedan" } },
    } },

    "e7-brisa": { kind: "dialogo", need: { era: 7, layer: 1 }, who: { brisa: "Brisa, voz del Coro" }, start: "a", nodes: {
      a: { say: [[null, "En el balcón de piedra del Coro, una mujer de unos treinta y cinco años, con el pelo atado con cintas de colores, ensaya frente al viento. Tiene una voz que se mete en los huesos."],
                 ["brisa", "Brisa. Me acuerdo de usted. O de alguien como usted. Era chica, y alguien me enseñó algo para cantar en el viento. Desde entonces no paré."],
                 ["brisa", "Soy la voz del Coro. Canto lo que se vende. Quiero una sola cosa: que los Altos no vuelvan a bajar a pedir. Nunca más. Para eso canto."]],
           opts: [{ t: "«Le enseñé la nana. ¿Todavía la canta?»", go: "nana", cNeed: "e6_brisaNana" },
                  { t: "«Yesquero le pagaba una moneda por día.»", go: "moneda", cNeed: "e6_brisaVende" },
                  { t: "«¿Qué canta cuando nadie paga?»", go: "gratis", once: true },
                  { t: "«Cánteme la canción de esta semana.»", go: "cantar" },
                  { t: "«Cante lo mismo para todos. Para el que paga y para el que no.»", go: "igual" }] },
      nana: { say: [["brisa", "La nana. La canto todas las noches, sola, en el balcón, para que la cumbre duerma. No la vendo. Nadie me la pidió nunca. Es lo único que el Coro no sabe que canto."]], back: "a" },
      moneda: { say: [["brisa", "Una moneda. Mi primera moneda. La tengo colgada del cuello. Yesquero se hizo rico con el musgo y después le contó al Coro lo del viento. Así empezó todo."],
                      ["brisa", "No le guardo rencor. Me enseñó lo que valía mi voz. Desde entonces no la regalo."]], back: "a" },
      gratis: { say: [["brisa", "Nada. Cuando nadie paga, no canto. Me guardo la voz. Una voz como la mía se gasta."],
                      ["brisa", "Bueno. La nana. Pero eso no cuenta."]], back: "a" },
      cantar: { say: [[null, "Brisa canta. Es una canción sobre los Altos, sobre la nieve, sobre gente que no se rinde. Es hermosa. Te dan ganas de subir a vivir a la cumbre."],
                      [null, "Después ves que, en el balcón de abajo, un comerciante del Prado la escucha cantar otra: sobre el Prado, sobre los faroles, sobre gente que no se rinde. La misma música. Otra letra."],
                      ["brisa", "Cada uno quiere oírse a sí mismo. Yo se los doy. ¿Eso es mentir? No sé. Es cantar."]], end: { xp: 10, flag: "e7_brisaTuya" } },
      igual: { say: [["brisa", "¿Lo mismo para todos? Entonces nadie va a sentir que la canción es suya."],
                     [null, "Lo prueba una tarde. Canta la misma letra para el Prado, para la Hondonada y para los Altos. La mitad no la compra. La otra mitad la canta junta, en tres pueblos a la vez."],
                     ["brisa", "Vendí menos. Pero hoy tres pueblos cantaron lo mismo sin pelearse por la letra. No sé si me conviene. Me gustó."]], end: { xp: 18, flag: "e7_brisaIgual" } },
    } },

    "e7-arpegia": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { arpegia: "Arpegia, la que habla con las manos", brisa: "Brisa, voz del Coro" }, start: "a", nodes: {
      a: { say: [[null, "En el mirador viejo de la cumbre, donde hace mucho alguien tarareaba descalzo, una mujer flaca mueve las manos frente al viento. No hace ningún ruido. La gente pasa y no la mira."],
                 ["arpegia", "(Con las manos, despacio, para que puedas seguirla) Arpegia. Así se dice mi nombre: dos dedos que bajan como lluvia. No oigo. Nunca oí. Las canciones del viento no se me pegan."],
                 ["arpegia", "(Con las manos) Mi familia guardaba promesas en canciones. Yo no puedo. Entonces las guardo así. Una promesa con las manos no depende del sonido. No se la lleva el viento. No la vende nadie."]],
           opts: [{ t: "Aprender a decir «prometo» con las manos", go: "aprender" },
                  { t: "Pedirle a Brisa que traduzca lo que dice Arpegia", go: "brisa" },
                  { t: "Saludarla e irte", go: "irte" }] },
      aprender: { say: [[null, "Te quedas toda la tarde. Arpegia te enseña: la mano abierta sobre el pecho, después cerrada, después hacia el otro. «Prometo». Lo repites hasta que te sale."],
                        ["arpegia", "(Con las manos, sonriendo) Ya está. Eso que hiciste no lo oyó nadie. Ni la Raíz. Solo yo. Ahora lo tienes que cumplir igual. Eso es lo difícil."],
                        [null, "Al irte, ves que te mira desde el mirador, con la mano abierta sobre el pecho."]], end: { xp: 18, flag: "e7_manosAprendidas" } },
      brisa: { say: [[null, "Brisa sube al mirador de mala gana. Mira las manos de Arpegia. Traduce en voz alta."],
                     ["brisa", "Dice que mi voz es linda. Que la oye con los pies, cuando canto fuerte. Que no le crea a mi propia canción. Que yo... no. Eso no lo voy a traducir."],
                     [null, "Brisa se va. Arpegia sigue moviendo las manos un rato, hacia donde se fue."]], end: { xp: 12, flag: "e7_arpegiaBrisa" } },
      irte: { say: [[null, "La saludas con la cabeza. Ella te devuelve el saludo con la mano, un gesto que no entiendes. Sigue hablándole al viento."]], end: { xp: 4, flag: "e7_arpegiaSola" } },
    } },

    "e7-coro": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { bordon: "Bordón, tesorero del Coro", brisa: "Brisa, voz del Coro", pregonero: "Pregonero, cantor de plazas" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Coro, tres personas cuentan monedas sobre una mesa larga. La voz, el que cobra y el que canta en las plazas. Una pintura vieja en la pared muestra a otros tres, hace muchas generaciones, votando con la mano levantada."],
                 ["bordon", "Bordón, tesorero. El Coro de los Tres gobernaba los Altos con votos. Ahora gobierna el Claro con canciones. Dicen que los Altos repartieron los versos, hace mucho. Antes era mentira. Ahora es verdad, y cobramos."],
                 ["pregonero", "Pregonero, para servirle. Yo los canto primero, en las plazas. Si yo la canto primero, se pega. Y nos hacemos ricos. Queremos que usted sea parte. La gente le cree."]],
           opts: [{ t: "Aceptar ser socio del Coro", go: "socio" },
                  { t: "«No.»", go: "no" },
                  { t: "«Una canción gratis por semana, para todos. Esa es mi condición.»", go: "gratis" }] },
      socio: { say: [["bordon", "Bien. Su parte."],
                     [null, "Te da una bolsa de monedas. Al día siguiente, Pregonero canta en la plaza del Prado una canción que dice tu nombre, tu criatura, el Vado. Se pega. Todos la cantan."],
                     ["brisa", "Ahora tiene fama. Y la fama es nuestra. Cuando no le guste lo que cantamos, va a tener que cantarlo igual. Así funciona."]], end: { xp: 10, coins: 20, flag: "e7_coroSocio" } },
      no: { say: [["bordon", "No. Claro. Usted no necesita la plata."],
                  ["pregonero", "Ojo, eh. Si no está con el Coro, el Coro puede cantar de usted. Lo que quiera. Y se pega igual."],
                  [null, "Brisa no dice nada. Te mira irte con una cara que no sabes leer."]], end: { xp: 12, flag: "e7_coroNo" } },
      gratis: { say: [["bordon", "¿Gratis? ¿Una por semana? Eso es la mitad de lo que ganamos."],
                      [null, "Discuten toda la tarde. Brisa vota que sí. Pregonero vota que no. Bordón cuenta monedas y, al final, vota que sí."],
                      ["bordon", "Una por semana. Gratis. Que la elija Brisa. Si nos arruinamos, le mando la cuenta."]], end: { xp: 18, flag: "e7_coroGratis" } },
    } },

    "e7-vado": { kind: "dialogo", need: { era: 7, layer: 2 }, who: { brisa: "Brisa, voz del Coro" }, start: "a", nodes: {
      a: { say: [[null, "Brisa baja al Vado. Es la primera vez que la ves fuera de la cumbre. Mira tu casa, a tu criatura, el agua. Tararea sin darse cuenta."],
                 ["brisa", "Cada pueblo del Claro tiene su canción. La compraron. El Prado, la Hondonada, hasta el Fondo. El Vado no tiene. La gente pasa por aquí y no sabe qué cantar."],
                 ["brisa", "El Coro le vende una. Le hago precio. O... no sé. Usted podría escribir una. Nunca vi a alguien escribir una canción para su propia casa."]],
           opts: [{ t: "Comprarle una canción para el Vado", go: "comprar", fx: { cost: 25 } },
                  { t: "Escribir una canción para el Vado", go: "escribir" },
                  { t: "«El Vado no necesita canción.»", go: "sin" }] },
      comprar: { say: [[null, "Le pagas. Brisa canta en el agua del Vado, despacio. Es una canción sobre un lugar donde se cruza el río y la gente se espera. Es buena. Se pega."],
                       [null, "Desde ese día, quien pasa por el Vado la tararea. Tu criatura también. Se duerme con ella."],
                       ["brisa", "Ya tiene canción. Es mía, pero es suya. Así es con las canciones compradas: nunca terminan de ser de uno."]], end: { xp: 12, flag: "m7_vadoComprada" } },
      escribir: { say: [[null, "Te sientas en la orilla con Brisa toda la tarde. Escribes. Tachas. No rima. Brisa se ríe, después se calla, después te ayuda con una palabra."],
                        [null, "Al anochecer, la cantas. Suena mal. Tu criatura la canta contigo, peor. Brisa no la canta en el viento: dice que no se lo merece el viento."],
                        ["brisa", "No se pega. Nadie la va a tararear sin querer. La van a cantar los que quieran. Eso es raro. Eso es bueno."]], end: { xp: 20, flag: "m7_vadoPropia" } },
      sin: { say: [["brisa", "¿Sin canción? ¿Y qué van a cantar los que pasen?"],
                   [null, "Lo que quieran, le dices. Brisa mira el agua un rato largo."],
                   ["brisa", "Lo que quieran. Hace años que nadie canta lo que quiere. Van a cantar lo que les vendimos en otro lado. Pero aquí, por lo menos, no lo pusimos nosotros."]], end: { xp: 14, flag: "m7_vadoSin" } },
    } },

    "e7-verso": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { bordon: "Bordón, tesorero del Coro" }, start: "a", nodes: {
      a: { say: [[null, "Bordón te llama a la sala del Coro. Sobre la mesa hay una hoja con un verso escrito. No rima. Lo reconoces."],
                 ["bordon", "El noveno verso. La condición del pacto. Con los molinos, en una semana lo canta todo el Claro. Todos lo saben, todos lo repiten, nadie lo olvida. Imagínese."],
                 ["bordon", "Y si se vuelve canción de moda, se puede cobrar. Por cantarlo en una boda, en un velorio, en un pacto. El Coro tendría el verso que sostiene el Claro. ¿Lo dejamos?"]],
           opts: [{ t: "«¿Cómo lo consiguieron, si después del Velo nadie lo recordaba?»", go: "velo", cNeed: "m6_velo", once: true },
                  { t: "«Se dijo en voz alta cuando se dijeron los nombres. ¿Por qué venderlo?»", go: "nombres", cNeed: "m6_nombres", once: true },
                  { t: "«El verso estaba guardado en un nombre. ¿De dónde salió esto?»", go: "guardado", cNeed: "m6_guardado", once: true },
                  { t: "Dejar que lo vendan", go: "vender" },
                  { t: "Impedirlo", go: "impedir" }] },
      velo: { say: [["bordon", "Nadie lo recordaba. La piedra sí. En las Cuevas hay una pared vieja con versos de tambor. Ahí estaba, en una esquina, con una firma que nadie sabe leer."]], back: "a" },
      nombres: { say: [["bordon", "Porque se dijo, sí. Una vez. Todos lo oyeron y nadie lo aprendió. No rima, no tiene música. Las cosas que no se cantan se olvidan. Nosotros le pusimos música. Eso vale."]], back: "a" },
      guardado: { say: [["bordon", "Esto no es el verso. Es lo que creemos que es. Tres versiones de taberna, mezcladas. El de verdad lo tiene alguien. Una mujer de las Mareas, dicen. La estamos buscando."],
                        ["bordon", "Cuando la encontremos, tendremos el bueno. Mientras, vendemos este."]], back: "a" },
      vender: { say: [["bordon", "Bien. Es un buen negocio para todos."],
                      [null, "A la semana, el noveno verso suena en todo el Claro, con una música pegajosa. Los chicos lo saltan en la plaza. Las parejas lo cantan al casarse y le pagan al Coro."],
                      [null, "En el Corazón, la Raíz se mueve. Algo que era una condición ahora es una canción de moda. Nadie sabe si eso la ata más o la suelta."]], end: { xp: 10, coins: 15, flag: "m7_versoVendido" } },
      impedir: { say: [[null, "Agarras la hoja y la rompes delante de Bordón. Él no se mueve."],
                       ["bordon", "Tengo copias. Pero entendí. Si usted se opone, la gente se va a enterar, y una canción que el Cuidador odia no se vende bien."],
                       ["bordon", "Lo guardo. No lo quemo. Algún día alguien lo va a querer comprar más caro que hoy. Paciencia."]], end: { xp: 18, flag: "m7_versoImpedido" } },
    } },
  });

  /* ---------- Prado Aurora: la plaza que canta lo mismo, Tarará y el Pregonero ---------- */
  add("aurora", {
    "e7-plaza": { kind: "encuentro", need: { era: 7, layer: 1 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En la plaza grande del Prado, cien personas cantan la misma canción mientras hacen otras cosas: venden pan, barren, discuten. La canción es de esta semana. Habla de lo lindo que es el Prado."],
                 [null, "Una mujer del Barrio, sentada en un banco, trata de cantar otra cosa. Le sale la de la semana. Lo intenta otra vez. Otra vez la de la semana. Se tapa la boca."],
                 [null, "«Tenía una canción mía. De cuando era chica. No me sale. Se me fue debajo de esta»."]],
           opts: [{ t: "Proponer una noche en que cada uno cante una canción propia", go: "noche" },
                  { t: "Ayudarla a recordar la suya, de a una palabra", go: "recordar" },
                  { t: "«Que el Barrio compre la próxima canción y la elija.»", go: "comprar" }] },
      noche: { say: [[null, "Hablas con los vecinos del Barrio. Esa noche, en la plaza, se juntan. La regla es simple: nadie canta lo del Coro. Cada uno lo suyo."],
                     [null, "Al principio no sale nada. Después un viejo canta algo de su madre. Una niña inventa. La mujer del banco encuentra tres palabras de la suya. La plaza suena horrible: cien canciones a la vez."],
                     [null, "Es el ruido más lindo que oíste en el Prado. Al día siguiente, el Barrio repite la noche. Le pone nombre: «la noche de las voces»."]], end: { xp: 20, flag: ["e7_plazaVoces", "u7_barrio"] } },
      recordar: { say: [[null, "Te sientas con ella. Le preguntas cómo era su casa, su madre, qué olía en la cocina. De a poco salen palabras. Una. Dos. Una tonada."],
                        [null, "Al final la canta entera, bajito. Es una canción de cuna mal rimada. Llora."],
                        [null, "«La tengo. Me la voy a cantar todas las mañanas antes de salir. Para que no me la tape la de la semana»."]], end: { xp: 16, flag: "e7_plazaRecuerda" } },
      comprar: { say: [[null, "El Barrio junta monedas una semana entera. Compra una canción al Coro y elige la letra: habla de la mesa larga y de la gente que come junta."],
                       [null, "La semana siguiente, todo el Prado canta la canción del Barrio. Las Casas también, sin darse cuenta. Les molesta cuando se dan cuenta."]], end: { xp: 10, flag: "e7_plazaComprada" } },
    } },

    "e7-tarara": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { tarara: "Tarará, niña del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En una casa del Prado, una niña de nueve años canta sin parar, sentada en la cama. Su madre le tapa la boca con la mano. La niña sigue cantando a través de la mano."],
                 ["tarara", "Tarará. Me llamo Tarará. No puedo parar. Todas las canciones del viento se me quedan. Todas a la vez. Canto despierta. Canto dormida. Quiero silencio. Una vez."],
                 [null, "La madre dice que en la Hondonada hay sombra de olvido todavía, en frascos. Que con un poco, la niña se olvidaría de todas las canciones. De todas. Hasta de la nana."]],
           opts: [{ t: "Llevarla a la Hondonada, a la sombra de olvido", go: "olvido" },
                  { t: "Enseñarle a cantar con las manos, como Arpegia", go: "manos", cNeed: "e7_manosAprendidas" },
                  { t: "«Que cante. Es su voz.»", go: "cantar" }] },
      olvido: { say: [[null, "La llevas a la Hondonada con su madre. Una sombra vieja abre un frasco. Tarará respira. Se queda callada, por primera vez en años."],
                      ["tarara", "..."],
                      [null, "Silencio. La niña sonríe. Al día siguiente no sabe ninguna canción. Tampoco la nana. Su madre se la canta a la noche y Tarará la mira como a una desconocida."]], end: { xp: 12, flag: "m7_tararaCallada" } },
      manos: { say: [[null, "Le enseñas a Tarará lo que te enseñó Arpegia: «prometo», «silencio», «gracias». Después la llevas a la cumbre, al mirador."],
                     [null, "Arpegia le toma las manos. Le enseña a cantar con ellas: mover las manos al ritmo de lo que le suena adentro, en vez de abrir la boca. Tarará prueba. La boca se le cierra. Las manos cantan."],
                     ["tarara", "(Con las manos, torpe, feliz) Silencio. Tengo silencio afuera. Adentro sigue. Pero afuera, silencio."]], end: { xp: 20, flag: "m7_tararaManos" } },
      cantar: { say: [["tarara", "¿Que cante? Pero me duele la garganta. Me duele la cabeza."],
                      [null, "La madre te mira con rabia. Tarará sigue cantando. Esa noche canta dormida, todas las canciones del Claro, mezcladas, una detrás de otra."],
                      [null, "Los vecinos se juntan en la ventana a escucharla. Algunos lloran. Dicen que canta canciones que no se oyen desde hace generaciones. Ella no sabe de dónde las saca."]], end: { xp: 10, flag: "m7_tararaCanta" } },
    } },

    "e7-pregonero": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { pregonero: "Pregonero, cantor de plazas" }, start: "a", nodes: {
      a: { say: [[null, "En la escalinata de las Casas del Farol, un hombre de chaqueta amarilla canta a gritos, con una voz que suena como un trueno. La gente se para a oírlo."],
                 ["pregonero", "Pregonero, el primero en cantar lo que se va a pegar. Hoy canto para las Casas del Farol. Me pagaron. «Las Casas que alumbran, las Casas que dan». Dentro de una semana, la canta el Barrio."],
                 ["pregonero", "Yo canto lo que me pagan. ¿Qué voy a hacer? Si no lo canto yo, lo canta otro. Mejor yo, que canto bien."]],
           opts: [{ t: "Convencer a las Casas de que su canción sea de todo el Prado", go: "casas" },
                  { t: "Pagarle para que cante la verdad sobre las Casas", go: "pagar", fx: { cost: 10 } },
                  { t: "Dejarlo cantar", go: "dejar" }] },
      casas: { say: [[null, "Hablas con las Casas del Farol en su salón. Les cuentas lo que pasa con las canciones compradas: que se pegan, que tapan. Que el Barrio las canta sin querer y las odia por eso."],
                     [null, "Un viejo de las Casas, con un libro gastado de su abuelo bajo el brazo, escucha. Dice que en su familia hubo uno que escribió la verdad cuando nadie quería. Que eso no se compra."],
                     [null, "Al día siguiente, las Casas le pagan a Pregonero para que cante una canción sin letra sobre ellas. Solo música. Que cada uno le ponga lo que quiera. El Barrio le pone insultos. Las Casas se ríen. Es la primera vez."]], end: { xp: 20, flag: ["e7_casasCantan", "u7_luz"] } },
      pagar: { say: [["pregonero", "¿La verdad? Cuesta lo mismo. Canto lo que me pagan, ya le dije."],
                     [null, "Canta, a gritos, la historia de la leña del invierno. Las Casas lo echan de la escalinata. Pregonero se va riéndose, con tus monedas."],
                     ["pregonero", "Mañana me pagan ellos para que cante otra cosa más fuerte. Usted me hizo ganar dos veces. Gracias."]], end: { xp: 10, flag: "e7_pregoneroVerdad" } },
      dejar: { say: [[null, "Pregonero sigue. Al rato, la plaza entera canta «las Casas que alumbran». Una mujer del Barrio la canta mientras barre, con cara de asco."]], end: { xp: 6, flag: "e7_pregoneroSigue" } },
    } },
  });

  /* ---------- Un pueblo por zona: el compás de forja, los setos, las sombras que cantan, las Mareas bajo el agua, el eco torcido y los sueños robados ---------- */
  add("crater", {
    "e7-compas": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { martinete: "Martinete, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la Forja Grande suena una canción de trabajo, rápida, que sale de una caja de madera con un tubo que da al viento. Los obreros martillan al compás. Hace catorce horas que martillan."],
                 ["martinete", "Martinete, capataz. El Gremio compró la canción. Con ella nadie se cansa. Bueno, se cansan, pero no se dan cuenta. Producimos el doble."],
                 [null, "Un obrero joven se desmaya junto al yunque. Los demás siguen martillando al compás. Martinete lo arrastra a un costado sin parar de tararear."]],
           opts: [{ t: "«Que a mediodía suene una canción de descanso.»", go: "descanso" },
                  { t: "Romper la caja de la canción", go: "romper" },
                  { t: "«El Gremio paga más por más horas. Que sigan.»", go: "seguir" }] },
      descanso: { say: [["martinete", "¿De descanso? ¿Una canción que haga parar?"],
                        [null, "Le pides a Brisa, en la cumbre, una canción lenta. Ella la canta en el viento a mediodía. En la Forja, los martillos bajan solos. Los obreros se sientan. Comen."],
                        ["martinete", "Una hora. Nadie quería parar y nadie podía. Ahora todos paran a la vez. El Gremio va a protestar. Los obreros, no. Ni yo."]], end: { xp: 20, flag: ["e7_cancionDescanso", "u7_fuego"] } },
      romper: { say: [[null, "Rompes la caja con un martillo de la forja. La música se corta a mitad de compás. Los obreros se quedan quietos, con los martillos en el aire."],
                      [null, "Después, uno por uno, se sientan en el suelo. Se miran las manos. Algunos lloran del cansancio que no sentían."],
                      ["martinete", "El Gremio manda otra caja mañana. Pero hoy se dieron cuenta de cuánto trabajaban. Eso no se lo saca una caja."]], end: { xp: 14, flag: "e7_compasRoto" } },
      seguir: { say: [["martinete", "Más horas, más paga. Así es."],
                      [null, "Los martillos siguen. El obrero desmayado se despierta, se levanta, vuelve al yunque. Tararea."]], end: { xp: 6, flag: "e7_compasPagado" } },
    } },
  });

  add("forest", {
    "e7-setos": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { ligustro: "Ligustro, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En el borde del Bosque, el Concejo plantó setos altísimos, apretados, de hojas negras. Del otro lado, el viento del fondo sopla con sus canciones. De este lado, nada."],
                 ["ligustro", "Ligustro, del Concejo del Musgo. Los setos no dejan pasar el viento. Ni las canciones. El Bosque no compra. El Bosque no se deja pegar nada."],
                 ["ligustro", "El problema es que ahora no se oye nada. Ni los pájaros. Ni la Raíz en el Largo Silencio. Los setos son demasiado buenos."]],
           opts: [{ t: "«Abran un hueco. Uno solo, para oír.»", go: "hueco" },
                  { t: "«Plántenlos más altos.»", go: "altos" },
                  { t: "Arrancar los setos", go: "arrancar" }] },
      hueco: { say: [[null, "Cortan un hueco en el seto, del tamaño de una puerta. Por ahí entra un poco de viento, un pedazo de canción, un pájaro."],
                     [null, "Los del Bosque se paran frente al hueco a escuchar. Algunos se van tarareando. Otros se tapan los oídos y vuelven."],
                     ["ligustro", "Un hueco. Así se escucha en el Bosque: un poco, con cuidado, eligiendo. Eso es lo que hacíamos en el Largo Silencio, antes. Lo habíamos olvidado."]], end: { xp: 20, flag: ["e7_setoHueco", "u7_planta"] } },
      altos: { say: [[null, "Los setos crecen otro metro. El Bosque queda en un silencio de algodón. Los chicos hablan bajito sin que nadie se los pida."],
                     ["ligustro", "Ninguna canción comprada. Ninguna. Y ningún pájaro. Supongo que es el precio."]], end: { xp: 8, flag: "e7_setosAltos" } },
      arrancar: { say: [[null, "Arrancas los setos con los jóvenes del Bosque, toda una semana. Las raíces son profundas. Al final, el viento entra de golpe, con todas las canciones del Claro."],
                        [null, "Esa noche, el Bosque entero canta la canción de la semana. Ligustro también. Se tapa la boca con la mano, furioso."]], end: { xp: 10, flag: "e7_setosFuera" } },
    } },
  });

  add("hollow", {
    "e7-sombras": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { sigilo: "Sigilo, sombra sin tierra" }, start: "a", nodes: {
      a: { say: [[null, "En la Hondonada, en las orillas de los pozos secos, viven sombras sin casa. Todas cantan. Bajo, sin parar, como un zumbido. Cuando te acercas, cantan más fuerte."],
                 ["sigilo", "Sigilo. Sombra sin tierra. Cantamos para que nadie nos nombre. Si hay canción, no se oye el nombre. Si no se oye, no te lo pueden usar. Nos lo enseñaron nuestras madres."],
                 ["sigilo", "Gastamos todo en canciones. Más que en pan. Una canción es una casa que te llevas puesta. Es la única que tenemos."]],
           opts: [{ t: "«Sus abuelas dijeron sus nombres en voz alta. Para eso se dispersó la Corte.»", go: "nombres", cNeed: "m6_nombres" },
                  { t: "Pedirle a la Hondonada que les dé una calle propia", go: "calle" },
                  { t: "Cantar con ellas", go: "cantar" },
                  { t: "«Dígame su nombre verdadero. No se lo voy a usar.»", go: "nombre" }] },
      nombres: { say: [["sigilo", "Los dijeron. Sí. Y después las echaron de todos lados con el nombre puesto, como un cartel. Por eso cantamos. Para que el cartel no se lea."],
                       ["sigilo", "La verdad fue buena para el Claro. Para nosotras fue una intemperie."]], back: "a" },
      calle: { say: [[null, "Vas al consejo de la Hondonada. Discuten dos días. Al final les dan una calle, la más vieja, junto al pozo del medio. Es poco. Es suya."],
                     [null, "La primera noche en la calle, las sombras no cantan. Duermen. Se oye el silencio de la Hondonada por primera vez en años."],
                     ["sigilo", "Una casa de verdad. Una calle. Ya no necesito la canción para estar adentro de algo. Ahora la canto cuando quiero."]], end: { xp: 20, flag: ["e7_sombrasCalle", "u7_sombra"] } },
      cantar: { say: [[null, "Te sientas con ellas y cantas. La canción es lenta, sin letra, un zumbido que sube y baja. Al rato no sabes dónde termina tu voz y empieza la de ellas."],
                      ["sigilo", "Ahora usted también se esconde. Es lindo, ¿no? Nadie te ve. Nadie te pide nada."]], end: { xp: 12, flag: "e7_sombrasCoro" } },
      nombre: { say: [[null, "Sigilo deja de cantar. Las otras también, de golpe. Te mira mucho rato."],
                      ["sigilo", "No. Usted no me lo va a usar. Pero otro sí, si lo oye. Gracias por pedirlo. Nadie lo pide: lo arrancan."],
                      [null, "Vuelve a cantar. Más bajo."]], end: { xp: 14, flag: "e7_sigiloNombre" } },
    } },
  });

  add("lake", {
    "e7-bajoagua": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { albufera: "Albufera, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "En el Lago Espejo, la gente de las Mareas se sumerge en grupos, todos juntos, y se queda abajo mucho rato. En la superficie suben burbujas, en ritmo."],
                 ["albufera", "Albufera, de las Mareas. Mi abuela aprendió a nadar con Ondina. Nosotros cantamos abajo. El viento no llega al fondo del lago. Lo que se canta abajo es nuestro. No se pega a nadie."],
                 ["albufera", "Arriba nadie lo entiende. Dicen que hacemos ruido de pez. El Coro vino a comprarlo, una vez. Quería saber qué cantamos. No le dijimos."]],
           opts: [{ t: "Sumergirte con ellos y escuchar", go: "abajo" },
                  { t: "«El Coro pagaría bien. Véndanle una.»", go: "vender" },
                  { t: "Quedarte en la orilla", go: "orilla" }] },
      abajo: { say: [[null, "Respiras hondo y bajas con ellos. Abajo el agua es verde y quieta. Albufera canta con la boca cerrada. Las burbujas suben en un ritmo lento. Lo sientes en el pecho más que en los oídos."],
                     [null, "Es la nana. Pero distinta: más lenta, con notas que no conoces, como si debajo del agua se hubiera conservado de otra forma."],
                     ["albufera", "Ahora la oyó. Abajo. No se la lleve arriba. Arriba se pega y se rompe. Aquí se queda entera."]], end: { xp: 20, flag: ["e7_burbujas", "u7_agua"] } },
      vender: { say: [["albufera", "¿Venderla? ¿Lo único que el viento no nos sacó?"],
                      [null, "Al final venden una canción vieja de pesca. El Coro la carga en el viento. A la semana, todo el Claro canta una canción de pesca de las Mareas, rápida, alegre, sin burbujas."],
                      ["albufera", "No es la nuestra. Es una que se parece. Así se vende todo: que se parezca."]], end: { xp: 10, coins: 10, flag: "e7_burbujasVendidas" } },
      orilla: { say: [[null, "Te quedas en la orilla mirando las burbujas. Suben, revientan, suben. Al rato los de las Mareas salen, respirando fuerte, y se secan sin hablar de lo que cantaron."]], end: { xp: 6, flag: "e7_burbujasSolas" } },
    } },

    "e7-guardiana": { kind: "dialogo", need: { era: 7, layer: 2, flag: "m6_guardado" }, who: { albufera: "Albufera, de las Mareas" }, start: "a", nodes: {
      a: { say: [[null, "Albufera te lleva de noche a una choza en una isla chica del lago. Adentro hay una mujer de unos cuarenta años, de sombra, con los labios apretados. No te saluda."],
                 ["albufera", "No le pregunte cómo se llama. Nunca. Su nombre es el verso. Se lo dieron de niña, frente a los nueve pueblos. Vive con nosotras desde entonces. Tiene una hija."],
                 ["albufera", "El Coro la está buscando. Mandó gente al lago. Si la encuentran, la van a hacer cantar. O a su hija. Un verso así, pegado en el viento, vale más que todos los molinos."]],
           opts: [{ t: "Esconderlas más lejos, en el Fondo", go: "esconder" },
                  { t: "Enseñarles a decir el verso con las manos, sin sonido", go: "manos", cNeed: "e7_manosAprendidas" },
                  { t: "«Que lo cante una vez, libre. Que deje de cargarlo.»", go: "cantar" }] },
      esconder: { say: [[null, "Esa misma noche llevas a la mujer y a la niña hacia el Fondo Blanco, en barca y después a pie. Grumo, el soñador mayor, les da una cama de hielo en una sala vieja."],
                        ["albufera", "Ahí no llega el viento. No llega el Coro. No llega nadie. La niña va a crecer en el frío, con soñadores. No sé si eso es salvarla."]], end: { xp: 16, flag: "e7_guardianaEscondida" } },
      manos: { say: [[null, "Le muestras a la mujer los gestos de Arpegia. Ella mira. Mueve las manos, despacio, como quien prueba una llave."],
                     [null, "Después hace algo que no le enseñaste: dice su nombre con las manos. El verso entero. Sin sonido. Lo ves y no lo entiendes. Ella llora."],
                     ["albufera", "Lo dijo. Por primera vez en su vida. Nadie lo oyó. Ni el viento, ni el Coro, ni la Raíz. Solo nosotras lo vimos. Ahora sabe que puede."]], end: { xp: 22, flag: "e7_guardianaManos" } },
      cantar: { say: [["albufera", "¿Cantarlo? ¿Soltarlo? Si lo canta, deja de ser suyo. Es de todos. Y el Coro lo carga en el viento al día siguiente."],
                      [null, "La mujer te mira. Abre la boca. La cierra. Niega con la cabeza, despacio."],
                      [null, "Al irte, la oyes tararear algo detrás de la puerta, muy bajito. No es el verso. Es la nana. La que canta cuando no puede decir su nombre."]], end: { xp: 12, flag: "e7_guardianaCalla" } },
    } },
  });

  add("caves", {
    "e7-ecotorcido": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { cuarcita: "Cuarcita, de la Hondura" }, start: "a", nodes: {
      a: { say: [[null, "En las Cuevas, el eco repite las canciones del viento una y otra vez, día y noche. Pero cada vez que las repite, las cambia un poco. Lo que entra como canción de amor sale como insulto."],
                 ["cuarcita", "Cuarcita, de la Hondura. Mi madre era Mica. Grababa lo que otros borraban. Yo grabo lo que el eco tuerce. Ya no sé cuál es la canción verdadera y cuál es la torcida."],
                 ["cuarcita", "Lo peor es que las torcidas se pegan más. La gente de arriba ya las canta torcidas. Se pelean por versos que el eco inventó."]],
           opts: [{ t: "Grabar la letra original de cada canción, al lado del eco", go: "grabar" },
                  { t: "Tapar la galería del eco", go: "tapar" },
                  { t: "«Vendan las torcidas. Se pegan más.»", go: "vender" }] },
      grabar: { say: [[null, "Durante una semana, con Cuarcita, escuchas cada canción cuando entra, antes de que el eco la toque, y la grabas en la pared, palabra por palabra."],
                      [null, "Al lado, Cuarcita graba lo que sale. Dos columnas. La gente baja a comparar. Algunos se ríen. Otros se dan cuenta de por qué se pelearon."],
                      ["cuarcita", "Ahora se puede ver qué hizo el eco. Mi madre decía: la piedra no elige. Pero sí se puede poner al lado lo que fue y lo que quedó."]], end: { xp: 20, flag: ["e7_letrasGrabadas", "u7_piedra"] } },
      tapar: { say: [[null, "Tapan la boca de la galería con piedras. El eco se apaga del otro lado, despacio, como alguien que se queda dormido hablando."],
                     ["cuarcita", "Callado. Ahora las canciones no se tuercen aquí. Se tuercen en otro lado, en las cabezas. Eso no se tapa."]], end: { xp: 10, flag: "e7_ecoTapado" } },
      vender: { say: [["cuarcita", "¿Vender? ¿Nosotros? La Hondura no vende memoria."],
                      [null, "Al final un picador joven lo hace a escondidas: le lleva al Coro tres canciones torcidas. Se pegan en una semana. Una es un insulto a las Mareas. Hay peleas en la orilla."],
                      ["cuarcita", "La Hondura vendió algo. Por primera vez. Y fue lo peor que teníamos."]], end: { xp: 6, flag: "e7_ecoVendido" } },
    } },
  });

  add("deep", {
    "e7-suenos": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { grumo: "Grumo, soñador mayor" }, start: "a", nodes: {
      a: { say: [[null, "En la sala de los soñadores del Fondo, la gente se despierta vacía, con los ojos secos. Un hombre de unos treinta y tantos, con el pelo blanco de escarcha desde chico, camina entre las camas."],
                 ["grumo", "Grumo. Soñador mayor. Antes soñábamos lo que otros olvidaban. Ahora el viento nos lo saca de noche. Sube por las grietas del hielo. A la mañana, en la cumbre, alguien canta lo que soñamos."],
                 ["grumo", "No sé si es un alivio o un robo. Los soñadores ya no lloran. Pero tampoco recuerdan nada. Se despiertan como una cama sin hacer."]],
           opts: [{ t: "«¿Sopor también lo sentía?»", go: "sopor", cNeed: "e6_soporDespierta", once: true },
                  { t: "Tapar las grietas del hielo", go: "tapar" },
                  { t: "«Que se lo lleve. Ya cargaron bastante.»", go: "dejar" },
                  { t: "Que alguien cante la nana en la sala cada noche, de guardia", go: "nana" }] },
      sopor: { say: [["grumo", "Sopor. Me acuerdo de cuando no se despertaba. Y de cuando se despertó con la nana. Murió vieja, contando un sueño por mañana. Ella decía que los sueños eran de la Raíz y había que devolvérselos."],
                     ["grumo", "Pero no así. No por el viento, para que los venda el Coro."]], back: "a" },
      tapar: { say: [[null, "Tapan las grietas con nieve apretada y agua que se congela. El viento deja de entrar a la sala. Esa noche, los soñadores lloran dormidos otra vez."],
                     ["grumo", "Volvieron los sueños. Volvió el llanto. Por lo menos son nuestros. Alguien tiene que llorarlos, y no queremos que los cante un desconocido en la cumbre."]], end: { xp: 14, flag: "e7_grietasTapadas" } },
      dejar: { say: [["grumo", "Que se lo lleve. Sí. Estamos cansados."],
                     [null, "El viento sigue entrando. Los soñadores duermen como piedras. En la cumbre, el Coro estrena una canción que se parece mucho a un llanto."]], end: { xp: 8, flag: "e7_suenosVuelan" } },
      nana: { say: [[null, "Armas turnos. Cada noche, un soñador se queda despierto y canta la nana bajito, sentado junto a las grietas del hielo."],
                    [null, "El viento sigue entrando, pero cuando pasa por la nana, sale más lento. Los sueños se quedan un poco más. Los soñadores se despiertan con algo, aunque sea un pedazo."],
                    ["grumo", "Un pedazo. Eso queríamos. Ni todo ni nada. El Fondo siempre fue de repartir."]], end: { xp: 20, flag: ["e7_nanaGuardia", "u7_escarcha"] } },
    } },
  });

  /* ---------- Corazón del Claro: la nota del talón, la fiesta del Coro y el final ---------- */
  add("heart", {
    "e7-talon": { kind: "encuentro", need: { era: 7, layer: 1 }, who: {}, start: "a", nodes: {
      a: { say: [[null, "En el Corazón, entre las estatuas, el viento sale de una grieta al pie de la Raíz, donde la Raíz se hunde como un talón. Sale con una sola nota, larga, que no cambia."],
                 [null, "Nadie la compra. El Coro la probó en los molinos: no se pega. Nadie sabe cantarla. Es demasiado larga para una garganta."],
                 [null, "Si no te mueves, la sientes en el suelo, en los dientes, en el pecho de tu criatura."]],
           opts: [{ t: "Intentar cantar la nota, con tu criatura", go: "cantar" },
                  { t: "Escuchar sin hacer nada", go: "escuchar" },
                  { t: "Llevarle la nota al Coro", go: "coro" }] },
      cantar: { say: [[null, "Abres la boca y cantas la nota. Te quedas sin aire enseguida. Tu criatura sigue, con su voz chica. Cuando se cansa, vuelves tú. Así, por turnos, un buen rato."],
                      [null, "En algún momento, la nota de la Raíz y la de ustedes se juntan. El suelo deja de temblar. Por un segundo, el viento se calla."],
                      [null, "Después vuelve. Pero tu criatura se queda mirando la grieta como quien oyó su nombre."]], end: { xp: 18, flag: "e7_notaCantada" } },
      escuchar: { say: [[null, "Te sientas entre las estatuas y escuchas. La nota no cambia. Al rato, empiezas a oír cosas dentro: voces, pedazos de canciones viejas, un tambor, una nana."],
                        [null, "No es una nota. Son todas a la vez. Todo lo que el Claro cantó alguna vez, apretado en un solo sonido."]], end: { xp: 14, flag: "e7_notaOida" } },
      coro: { say: [[null, "Le describes la nota a Bordón, en la sala del Coro. Él anota. Brisa escucha desde la puerta."],
                    [null, "«No se vende», dice Bordón. «Ya la probamos». Brisa no dice nada. Esa noche, desde el balcón, la oyes intentar cantarla. Se le quiebra la voz."]], end: { xp: 10, flag: "e7_notaCoro" } },
    } },

    "e7-fiesta": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { pregonero: "Pregonero, cantor de plazas" }, start: "a", nodes: {
      a: { say: [[null, "El Coro organiza una fiesta en el Corazón. Cada pueblo trae su canción comprada y la canta frente a las estatuas, por turnos, más fuerte que el anterior."],
                 ["pregonero", "¡Nueve pueblos, nueve canciones, un solo Coro! El que cante más fuerte, gana. Y el premio es una canción nueva, gratis, que nadie más va a tener."],
                 [null, "Las canciones chocan en el aire. La Raíz, bajo las estatuas, cruje. Hay algo en el crujido que se parece a una queja."]],
           opts: [{ t: "Cantar la nota del talón en medio de la fiesta", go: "nota", cNeed: "e7_notaCantada" },
                  { t: "Pedir un minuto de silencio", go: "silencio" },
                  { t: "Dejar que sigan", go: "seguir" }] },
      nota: { say: [[null, "En medio del ruido, te pones frente a la grieta del talón y cantas la nota larga, con tu criatura. Al principio nadie te oye."],
                    [null, "Después alguien se calla para escuchar. Y otro. Las canciones compradas se apagan una por una. Queda la nota. Y, debajo, el suelo que deja de crujir."],
                    ["pregonero", "Bueno. Esa no se vende. Pero calla a todas las demás. Eso sí que es una canción."]], end: { xp: 20, flag: "e7_fiestaNota" } },
      silencio: { say: [[null, "Te subes a la base de una estatua y pides un minuto de silencio. Se ríen. Insistes. Al final, por cansancio, se callan."],
                        [null, "Un minuto. El viento sigue con su nota. La Raíz deja de crujir. Alguien, en el fondo, llora sin saber por qué."],
                        [null, "Después la fiesta sigue. Pero más baja."]], end: { xp: 16, flag: "e7_fiestaSilencio" } },
      seguir: { say: [[null, "La fiesta sigue hasta el amanecer. Gana el Prado, con una canción sobre faroles. La Raíz cruje toda la noche."],
                      [null, "A la mañana, entre las estatuas, hay una grieta nueva. Chica. De ahí sale otro viento, con otra nota."]], end: { xp: 8, flag: "e7_fiestaCoro" } },
    } },

    "e7-final": { kind: "dialogo", need: { era: 7, eraWin: "heart" }, first: true, once: true, who: { brisa: "Brisa, voz del Coro", arpegia: "Arpegia, la que habla con las manos", bordon: "Bordón, tesorero del Coro" }, start: "a", nodes: {
      a: { say: [[null, "La Raíz Cantora cae, y del talón sale un viento fuerte, lleno de todas las canciones del Claro a la vez. Las estatuas vibran. Frente a ellas están Brisa, Bordón y Arpegia."],
                 ["bordon", "Ahí está todo. Si cargamos los molinos con una sola canción, una sola, y todo el Claro se la canta a la Raíz, la Raíz se duerme. Por obligación, pero se duerme. Paz cantada."],
                 ["brisa", "O se rompen los molinos. Todos. El viento sale sin dueño. Las canciones dejan de valer. Yo dejo de valer. No sé si quiero eso. Sé que es lo justo."],
                 ["arpegia", "(Con las manos, y Brisa traduce, despacio) Hay una tercera. Prometer sin sonido. Que los pueblos se prometan cosas con las manos. La Raíz no lo va a oír. Pero ellos sí lo van a cumplir. Para eso tienen que estar los nueve."]],
           opts: [{ t: "«¿Qué pasa si todo el Claro canta una sola canción?»", go: "q1", once: true },
                  { t: "«¿Qué pasa si se rompen los molinos?»", go: "q2", once: true },
                  { t: "«¿Qué pasa con promesas que la Raíz no oye?»", go: "q3", once: true },
                  { t: "Hacer que todo el Claro cante una sola canción", go: "unico" },
                  { t: "Romper los molinos", go: "libre" },
                  { t: "Enseñar el Canto de Manos a los nueve pueblos", go: "manos", cNeed: "e7_nueve" }] },
      q1: { say: [["bordon", "La Raíz duerme. Las plazas cantan lo mismo, todos los días, para que siga dormida. Nadie elige qué cantar. Pero nadie tiene miedo."],
                  ["brisa", "Y en cada plaza va a quedar algo. Lo dicen los viejos de la cumbre: cuando se obliga a dormir a la Raíz, nacen estrellas que no hablan. Mudas. Llenas de promesas que nadie quiso hacer."]], back: "a" },
      q2: { say: [["brisa", "El viento vuelve a ser de todos. Y de nadie. Cualquiera canta lo que quiere, y se pega igual, un rato. Los rumores van a correr sin dueño. Nadie va a saber qué creer."],
                  ["bordon", "Y nada va a valer. Ni las canciones, ni las nanas. Si todo se pega, nada importa."]], back: "a" },
      q3: { say: [["arpegia", "(Con las manos) La Raíz escucha el sonido. Siempre escuchó eso: el canto, la nana, el verso. Lo que no suena, no le llega."],
                  ["brisa", "Dice que los pueblos van a tener pactos entre ellos que la Raíz no conoce. Que eso puede ser bueno. O que la Raíz, un día, se va a enterar de que la dejaron afuera."]], back: "a" },
      unico: { say: [[null, "Bordón da la orden. Brisa canta en los doce molinos a la vez. Una sola canción, lenta, simple. El viento la lleva a todo el Claro en una noche."],
                     [null, "A la mañana, en cada plaza, la gente la canta sin poder parar. Hacia el Corazón. La Raíz se queda quieta, como un chico al que le cantan demasiado fuerte."],
                     [null, "En la plaza del Prado aparece una estrella chica, opaca, flotando sobre la fuente. No brilla. No dice nada. A la semana hay una en cada plaza."],
                     ["brisa", "Duerme. Lo logramos. Ya no tengo que cambiar de canción según quién escucha. Ahora todos escuchan la misma. Y yo no la elegí."]], end: { xp: 60, flag: "m7_unico" } },
      libre: { say: [[null, "Subes a la cumbre con Brisa. Ella toma el hacha primero. Cortan las cuerdas de los doce molinos, uno por uno. Las aspas giran locas y se detienen."],
                     [null, "El viento del fondo pasa por la cumbre sin que nadie le cante adentro. Lleva sueños, ruidos, canciones a medias. Se pega un rato y se va."],
                     ["bordon", "Se terminó el negocio. Y el gobierno. Mañana, cualquiera canta cualquier cosa, y el Claro la cree un día."],
                     ["brisa", "Ya no valgo nada. Qué alivio. Y qué miedo."]], end: { xp: 60, flag: "m7_libre" } },
      manos: { say: [[null, "Llegan los nueve. El Barrio con su noche de las voces, las Casas con su canción sin letra, el Fuego con su hora de descanso, el Bosque con su hueco en el seto, los Altos con sus molinos de todos, las sombras con su calle, las Mareas mojadas, la Hondura con sus dos columnas, el Fondo con su guardia de nana."],
                     [null, "Arpegia se para en el centro. Les enseña: la mano abierta en el pecho, cerrada, hacia el otro. «Prometo». Los nueve lo repiten, en silencio, frente a frente."],
                     [null, "El viento sigue soplando con todas sus canciones. Pero entre los pueblos pasa algo que el viento no lleva. La Raíz, abajo, no oye nada. Se mueve, inquieta, como quien sabe que hablan de ella en otro cuarto."],
                     ["arpegia", "(Con las manos, y esta vez todos entienden) Ya está. Ahora cúmplanlo. Eso es lo difícil."]], end: { xp: 60, flag: "m7_manos" } },
    } },
  });


  /* ==================== Entrega 2: el Prado, el Cráter y el Bosque ==================== */

  /* ---------- Prado Aurora: la elección cantada, la escuela de canciones, la canción de odio, Tarará dormida, la casa del Pregonero, el farol que canta, el mercado del silencio y la mesa larga ---------- */
  add("aurora", {
    "e7-eleccion": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { hogaza: "Hogaza, del Barrio", quinque: "Quinqué, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Concejo del Prado hay dos tarimas. En una, una panadera del Barrio con harina en los brazos. En la otra, un muchacho de las Casas con un farol bordado en la chaqueta. Detrás de cada uno, alguien canta."],
                 ["hogaza", "Hogaza, del Barrio. Mañana se elige el Concejo. Ya no se vota con la mano: gana el que tenga la canción que más se canta. Nosotros juntamos para una. Ellos compraron tres."],
                 ["quinque", "Quinqué, de las Casas del Farol. No es culpa mía que la gente cante lo nuestro. Es mejor canción. Así funciona ahora. Antes ganaba el que más gritaba. Ahora el que mejor canta. Es un avance."]],
           opts: [{ t: "«Que se vote con la mano levantada, como antes.»", go: "mano" },
                  { t: "Ayudar al Barrio a escribir una canción propia, sin comprarla", go: "barrio" },
                  { t: "«Que gane la mejor canción. Así es ahora.»", go: "cancion" }] },
      mano: { say: [["quinque", "¿Con la mano? Eso es de los abuelos. La gente ya no sabe levantar la mano sin cantar."],
                    [null, "Hablas con el Concejo viejo. Aceptan probar: votación a mano alzada, en silencio, sin canción. La plaza está rara, callada. La gente se mira, insegura."],
                    [null, "Gana Hogaza por once manos. Quinqué baja de su tarima y le da la mano. Al día siguiente, las Casas compran una canción que dice que la votación fue trampa. Se pega."]], end: { xp: 18, flag: "e7_votoMano" } },
      barrio: { say: [[null, "Pasas la noche en la panadería del Barrio. Escriben entre todos una canción sobre el pan de la mañana y la gente que se levanta temprano. No rima del todo."],
                      [null, "Al día siguiente, el Barrio la canta en la plaza, sin viento, sin molino. Suena chiquita al lado de las tres canciones de las Casas."],
                      ["hogaza", "Perdimos. Pero la cantamos nosotros. Y la cantaron los que la quisieron, no los que la oyeron. La próxima vez, más gente la va a querer."]], end: { xp: 16, flag: "e7_cancionBarrio" } },
      cancion: { say: [[null, "Gana Quinqué. Su canción suena en todo el Prado tres días. El cuarto, el Coro vende una nueva y nadie se acuerda de quién ganó."],
                       ["hogaza", "Gobierna el que compra. Y el que compra es el que ya tenía. Eso no es nuevo. Lo nuevo es que lo cantamos."]], end: { xp: 8, flag: "e7_concejoCasas" } },
    } },

    "e7-escuela": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { retahila: "Retahíla, maestra del Prado" }, start: "a", nodes: {
      a: { say: [[null, "En la escuela del Prado, los chicos cantan las tablas de multiplicar, los nombres de los nueve pueblos, la historia del Claro. Todo con música del viento. Todo pegado."],
                 ["retahila", "Retahíla, maestra. Mi abuela enseñaba aquí, con un lápiz en el pelo. Yo enseño cantando. Aprenden todo en una semana. Nunca lo olvidan."],
                 ["retahila", "El problema es que solo saben lo que se canta. Si les pregunto algo que no tiene canción, se quedan en blanco. Y la historia que cantan es la que el Coro escribió."]],
           opts: [{ t: "«Mimbre llevaba a sus alumnos a leer las paredes de las Cuevas.»", go: "mimbre", cNeed: "e6_escuelaPared" },
                  { t: "«Enséñeles una cosa por semana sin canción.»", go: "sin" },
                  { t: "«Que inventen ellos las canciones de lo que aprenden.»", go: "inventar" },
                  { t: "«Si aprenden, aprenden. Siga.»", go: "seguir" }] },
      mimbre: { say: [["retahila", "Mi abuela. Sí. Dicen que molestaba a todos los padres. Que los chicos volvían a casa preguntando."],
                      ["retahila", "Ahora los chicos no preguntan. Cantan. Los padres están contentos. Eso me da miedo."]], back: "a" },
      sin: { say: [[null, "Retahíla prueba. Un día por semana, la clase es en silencio: se lee, se pregunta, se discute. Los chicos se aburren. Se enojan. Uno llora."],
                   [null, "Al mes, una niña levanta la mano en la clase cantada y pregunta: «¿Y si la canción está mal?». Retahíla se queda sin contestar."],
                   ["retahila", "Una pregunta. En un mes. Mi abuela tenía diez por día. Es un comienzo."]], end: { xp: 18, flag: "e7_escuelaSilencio" } },
      inventar: { say: [[null, "Los chicos inventan canciones de lo que aprenden. Son malas. Desafinan. Una sobre el Lago dice que el agua es de queso."],
                        [null, "Pero las inventaron ellos, y para inventarlas tuvieron que entender. Un chico de las Mareas corrige al de queso: el agua del Lago es fría, y una vez se congeló."],
                        ["retahila", "Discuten la letra. Eso es aprender. No se les pega nada: lo tienen que decidir."]], end: { xp: 18, flag: "e7_escuelaInventa" } },
      seguir: { say: [["retahila", "Sí. Aprenden. Rápido y bien."],
                      [null, "En el patio, los chicos cantan la historia del Claro. Dice que el Coro trajo la abundancia a los Altos. No dice nada de los molinos. Nadie pregunta."]], end: { xp: 6, flag: "e7_escuelaCoro" } },
    } },

    "e7-cancionodio": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { pregonero: "Pregonero, cantor de plazas" }, start: "a", nodes: {
      a: { say: [[null, "En el Prado se pegó una canción nueva, pegadiza, alegre. Habla de «los que no tienen nombre», «los que se esconden cantando», «los que roban de noche»."],
                 [null, "Anoche, tres chicos del Prado le pegaron a una sombra en el borde de la Hondonada. Cantaban la canción mientras le pegaban."],
                 ["pregonero", "Yo la canté primero, sí. Me pagaron. No sé quién: vino un hombre con capucha, de las Casas o del Gremio, no sé. ¿Qué quiere que haga? Ya está en el viento."]],
           opts: [{ t: "Escribir otra canción que la tape", go: "tapar" },
                  { t: "Averiguar quién la pagó", go: "quien" },
                  { t: "Pedirle a Brisa que cante la canción una vez más, pero con otra letra", go: "brisa" },
                  { t: "«Es solo una canción.»", go: "nada" }] },
      tapar: { say: [[null, "Con Pregonero escriben una canción sobre una sombra que canta para que la dejen en paz. Es triste. No es pegadiza."],
                     [null, "Pregonero la canta en la plaza, gratis, por primera vez en su vida. La gente la escucha. No la tararea. Pero se calla la otra un rato."],
                     ["pregonero", "No se pegó. Pero la escucharon. Eso tampoco lo sabía: que se puede escuchar una canción sin que se pegue. Me dio vergüenza. No sé de qué."]], end: { xp: 16, flag: "e7_odioTapado" } },
      quien: { say: [[null, "Preguntas en el Coro. Bordón no quiere decirte. Al final, por plata, te muestra el libro: la pagaron entre tres familias de las Casas y un capataz del Gremio."],
                     [null, "Lo dices en voz alta en la plaza del Prado. Las Casas lo niegan. El capataz no. Dice que las sombras le quitaron trabajo a su hermano."],
                     ["pregonero", "Ahora todos saben quién pagó. La canción se sigue cantando igual. Pero ya no es de nadie. Es de ellos. Eso pesa distinto."]], end: { xp: 18, flag: "e7_odioPagado" } },
      brisa: { say: [[null, "Le cuentas a Brisa. Ella se queda callada mucho rato. Esa noche, en los molinos, canta la misma música con otra letra: la sombra no roba, la sombra canta para no tener miedo."],
                     [null, "Al día siguiente, el Prado tararea la música con las dos letras mezcladas. Los chicos no saben cuál cantar. Paran."],
                     ["pregonero", "Brisa cantó gratis. Eso no lo había hecho nunca. Bordón está furioso. Yo... yo estoy contento. No me lo cuenten."]], end: { xp: 20, flag: "e7_odioBrisa" } },
      nada: { say: [["pregonero", "Solo una canción. Eso digo yo. Y cobro."],
                    [null, "La canción sigue un mes. Las sombras dejan de venir al Prado. Cuando el Coro vende otra, la de odio se olvida. Lo que hicieron los chicos, no."]], end: { xp: 6, flag: "e7_odioQueda" } },
    } },

    "e7-tararasueno": { kind: "encuentro", need: { era: 7, layer: 2, flag: "m7_tararaCanta" }, who: { tarara: "Tarará, niña del Prado" }, start: "a", nodes: {
      a: { say: [[null, "Frente a la casa de Tarará, de noche, hay gente. Mucha. Sentada en la calle, escuchando por la ventana. La niña canta dormida: canciones viejísimas, de generaciones que nadie recuerda."],
                 [null, "Una vieja reconoce una nana de su bisabuela. Un hombre llora con una canción de los faroleros que no se canta desde la Savia Negra."],
                 ["tarara", "(despierta, en la puerta, ojerosa) Tarará. ¿Vienen a oírme dormir? El Coro vino ayer. Quiere poner un molino al lado de mi cama."]],
           opts: [{ t: "«No dejen entrar al Coro.»", go: "coro" },
                  { t: "Escribir en un cuaderno lo que canta dormida", go: "cuaderno" },
                  { t: "Dejar que el Coro ponga el molino", go: "molino" }] },
      coro: { say: [[null, "Hablas con los vecinos. Esa noche ponen guardia en la puerta, por turnos. Cuando llega la gente del Coro, no los dejan pasar."],
                    ["tarara", "Son mías. Las canciones. Aunque no sé de dónde vienen. Mientras duermo, son mías. Los vecinos dicen que les gusta oírme. A mí me gusta que me cuiden."]], end: { xp: 16, flag: "e7_tararaCuidada" } },
      cuaderno: { say: [[null, "Pasas tres noches en el suelo del cuarto, con un cuaderno, escribiendo a la luz de una vela. Tarará canta. Tú anotas."],
                        [null, "Veintitrés canciones. Una, la más vieja, habla de un pacto y de alguien que cuida. La letra está rota, pero se entiende la mitad."],
                        ["tarara", "¿Eso canto? No sabía. Léamelo despierta. Quiero saber qué digo cuando duermo."]], end: { xp: 20, flag: "e7_tararaCuaderno" } },
      molino: { say: [[null, "El Coro pone un molino chico en el techo de la casa. Cuando Tarará canta dormida, el viento se lleva las canciones viejas y las suelta en todo el Claro."],
                      [null, "A la semana, el Prado canta canciones de hace cinco generaciones sin saber por qué. Alguno llora. El Coro cobra. A la madre le dan una moneda por noche."],
                      ["tarara", "Ya no son mías. Las sueño y se van. Me despierto sin nada."]], end: { xp: 8, flag: "e7_tararaMolino" } },
    } },

    "e7-pregonerohija": { kind: "dialogo", need: { era: 7, layer: 2 }, who: { pregonero: "Pregonero, cantor de plazas" }, start: "a", nodes: {
      a: { say: [[null, "Pregonero está sentado en la escalinata de su casa, con la chaqueta amarilla doblada en las rodillas. Tiene la voz ronca de tanto cantar. Una niña de seis años le tira de la manga."],
                 ["pregonero", "Mi hija. Me pide que le cante algo mío. Algo que no me hayan pagado. Y no tengo nada. Sé mil canciones. Ninguna es mía."],
                 ["pregonero", "Mi padre cantaba en las plazas. Mi abuelo también. Siempre lo que pagaban. ¿Qué le canto a una niña que no paga?"]],
           opts: [{ t: "Ayudarlo a escribir una canción para ella", go: "escribir" },
                  { t: "«Cántele la nana. No es de nadie.»", go: "nana" },
                  { t: "«Cántele la que más le guste de las que vendió.»", go: "vendida" }] },
      escribir: { say: [[null, "Se sientan los tres en la escalinata. Pregonero intenta. Le salen rimas de las plazas, frases de anuncio. Las tacha."],
                        [null, "Al final escribe cuatro líneas sobre una niña que le tira de la manga. Son torpes. Las canta bajito, sin voz de trueno."],
                        ["pregonero", "Es lo peor que canté en mi vida. Y es lo único mío. No se la voy a vender a nadie. Ni a usted."]], end: { xp: 20, flag: "e7_pregoneroPropia" } },
      nana: { say: [["pregonero", "La nana. Sí. La cantaba mi madre. No me la pagó nadie."],
                    [null, "La canta. Su voz de trueno se vuelve chica. La niña se duerme en su regazo, en la escalinata, en medio de la calle."],
                    ["pregonero", "No es mía. Pero tampoco es de ellos. Por ahora alcanza."]], end: { xp: 16, flag: "e7_pregoneroNana" } },
      vendida: { say: [[null, "Pregonero le canta «las Casas que alumbran», la que más se pegó este año. La niña la canta con él, feliz. Se la sabe."],
                       ["pregonero", "Se la sabe. Todos se la saben. Pensé que eso era bueno. Ahora no sé."]], end: { xp: 8, flag: "e7_pregoneroVendida" } },
    } },

    "e7-farol": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { quinque: "Quinqué, de las Casas del Farol" }, start: "a", nodes: {
      a: { say: [[null, "En lo alto del farol de las Casas, un muchacho mide las ventanas con una cuerda. Quiere poner un molino chico arriba, para cantar la canción de las Casas desde el punto más alto del Prado."],
                 ["quinque", "Quinqué, de las Casas. El farol está vacío. Lleno de libros viejos, nada más. Mi bisabuelo los dejó aquí. Nadie los lee. Con un molino, el farol vuelve a servir: alumbra con canciones."],
                 [null, "En un estante hay tres libros atados con un cordel. Uno dice «el falso», otro «el verdadero», el tercero está en blanco."]],
           opts: [{ t: "«Esos libros los dejó Tojo para el que subiera a limpiar el farol.»", go: "tojo", cNeed: "e6_librosGuardados" },
                  { t: "Leerle en voz alta el libro verdadero", go: "leer" },
                  { t: "«Ponga el molino. El farol es suyo.»", go: "molino" },
                  { t: "«Escriba en el libro en blanco lo que pasa ahora.»", go: "blanco" }] },
      tojo: { say: [["quinque", "¿Tojo? ¿El que escribió contra su propio tío? En las Casas no se dice ese nombre."],
                    ["quinque", "Mi abuela decía que tenía razón. Lo decía bajito, en la cocina. Nunca entendí de qué."]], back: "a" },
      leer: { say: [[null, "Le lees el libro verdadero: la leña del invierno, las sillas quemadas en el Barrio, los retratos. Quinqué escucha de pie, con la cuerda en la mano."],
                    ["quinque", "Eso no lo canta nadie. Nadie lo va a comprar. Por eso no lo sabía."],
                    [null, "No pone el molino. Baja con el libro bajo el brazo. A la semana, alguien en el Barrio dice que el muchacho de las Casas vino a comprar pan y pidió perdón sin decir por qué."]], end: { xp: 20, flag: "e7_farolLeido" } },
      molino: { say: [[null, "Quinqué pone el molino. Desde el farol, la canción de las Casas suena más alta que todas. El Prado la canta más que nunca."],
                      [null, "Los libros quedan en el estante, debajo del molino. El viento les sacude el polvo cada noche."]], end: { xp: 8, flag: "e7_farolMolino" } },
      blanco: { say: [["quinque", "¿Escribir yo? No sé escribir libros. Sé comprar canciones."],
                      [null, "Al final escribe una página. Dice que el Prado canta lo que compra, que su familia compra más, y que él no sabe si eso está bien. La firma."],
                      ["quinque", "Una página. Mi bisabuelo dejó un libro entero en blanco. Le falta mucho. Lo voy a seguir. Despacio."]], end: { xp: 18, flag: "e7_farolEscrito" } },
    } },

    "e7-musgo": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { musguito: "Musguito, nieto de Yesquero" }, start: "a", nodes: {
      a: { say: [[null, "En el mercado del Prado, un muchacho flaco vende bolitas de musgo en frascos. La gente se las mete en los oídos y se va contenta, sorda."],
                 ["musguito", "Musguito, nieto de Yesquero. Mi abuelo se hizo rico con el musgo y después con el viento. Yo vendo lo contrario: silencio. Dos monedas, un día sin canciones. Se vende más que el pan."],
                 ["musguito", "Lo raro es que los que compran silencio son los mismos que compran canciones. En la mañana se tapan. En la tarde se destapan para oír la de moda."]],
           opts: [{ t: "«¿Por qué no lo regala, si es musgo del Bosque?»", go: "regalar" },
                  { t: "Comprarle un frasco y probarlo", go: "probar", fx: { cost: 2 } },
                  { t: "«Su abuelo empezó todo esto.»", go: "abuelo" }] },
      regalar: { say: [["musguito", "¿Regalar? Mi abuelo me enseñó una sola cosa: lo que la gente necesita, se cobra. Lo que no necesita, se le hace necesitar."],
                       [null, "Lo piensa. Mira a una vieja que cuenta monedas para un frasco y no le alcanza. Le da uno sin cobrar. Se queda mirando la mano vacía."],
                       ["musguito", "Uno. Al que no le alcanza. Así no me arruino y duermo mejor. No le cuente a mi madre."]], end: { xp: 16, flag: "e7_musgoRegalado" } },
      probar: { say: [[null, "Te pones el musgo en los oídos. El Prado se apaga. Ves gente cantando con la boca abierta, sin sonido. Parecen peces."],
                      [null, "Por primera vez en semanas, en tu cabeza no suena la canción de moda. Suena otra cosa: tu propia voz pensando."],
                      [null, "Te sacas el musgo en la tarde. La canción de moda vuelve de golpe."]], end: { xp: 12, flag: "e7_musgoProbado" } },
      abuelo: { say: [["musguito", "Mi abuelo oyó a una niña cantar en el viento y se lo contó al Coro. Sí. Y lo hizo por plata. Y la plata me dio de comer."],
                      ["musguito", "Yo vendo el remedio de lo que él vendió. Eso no lo arregla. Pero algo es. ¿Usted qué vende?"]], end: { xp: 10, flag: "e7_musgoAbuelo" } },
    } },

    "e7-mesalarga": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { hogaza: "Hogaza, del Barrio" }, start: "a", nodes: {
      a: { say: [[null, "En la calle del Barrio está la mesa larga, la de la comida compartida. Pero cada silla tiene una cinta de color: la de la canción que compró la familia que se sienta ahí."],
                 ["hogaza", "Hogaza, del Barrio. Antes la mesa era una. Ahora es cinco mesas pegadas. Los de la cinta roja cantan la suya, los de la azul la suya. No se miran. Comen rápido."],
                 ["hogaza", "Mi madre decía que la mesa larga la armaron los del Barrio y los de las Casas, juntos, sin saber por qué se habían odiado. Ahora nos separan las canciones, y sabemos muy bien por qué."]],
           opts: [{ t: "«La mesa se armó cuando el Barrio y las Casas comieron juntos.»", go: "junta", cNeed: "e6_mesaJunta", once: true },
                  { t: "Sacar todas las cintas", go: "cintas" },
                  { t: "«Una comida a la semana, sin cantar.»", go: "callar" },
                  { t: "«Que cada mesa tenga su canción. Así están en paz.»", go: "cinco" }] },
      junta: { say: [["hogaza", "Eso. Comieron juntos sin acordarse del odio. Mi madre decía que fue raro y lindo. Que la mesa era larga porque no sabían dónde poner el borde."]], back: "a" },
      cintas: { say: [[null, "Esa noche, con Hogaza, sacas todas las cintas de las sillas. En la mañana, la gente llega y no sabe dónde sentarse."],
                      [null, "Se sientan mezclados. Alguien empieza a cantar su canción. Otro, la suya. Se pisan. Se ríen. Alguien le pasa el pan al de la otra canción."],
                      ["hogaza", "Una mesa otra vez. Ruidosa. Mal cantada. Mía."]], end: { xp: 20, flag: "e7_mesaUna" } },
      callar: { say: [[null, "Hogaza lo propone en voz alta. Una comida por semana, en la mesa larga, sin canción. Algunos protestan. La mayoría prueba."],
                      [null, "El primer día es incómodo. Se oye masticar. El segundo, alguien cuenta algo de su abuela. El tercero, se ríen."],
                      ["hogaza", "Sin canción hay que hablar. Se nos había olvidado cómo."]], end: { xp: 18, flag: "e7_mesaSilencio" } },
      cinco: { say: [["hogaza", "Paz. Sí. Cada uno en su pedazo."],
                     [null, "Al mes, los de la cinta roja corren su mesa medio metro. Queda un hueco. Nadie lo cierra."]], end: { xp: 6, flag: "e7_mesaPartida" } },
    } },
  });

  /* ---------- Cráter Tibio: el maestro del Gremio, la canción de huelga, los sordos de la forja, la aprendiz, la campana, las cuentas, la obrera vieja y el ritmo del yunque ---------- */
  add("crater", {
    "e7-azufre": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { azufre: "Azufre, maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la oficina del Gremio, un hombre de bigote gris firma un contrato con el sello del Coro. Encima de la mesa, una caja de canciones nueva, más grande que la de la Forja."],
                 ["azufre", "Azufre, maestro del Gremio. El Cráter pasó hambre tres veces en cien años. Con las canciones de trabajo producimos el doble. Vendemos a los Altos, al Fondo, afuera del paso. Nadie en el Cráter pasa hambre ahora."],
                 ["azufre", "Sé lo que va a decir. Que trabajan de más. Sí. Comen de más también. Elija: catorce horas y pan, u ocho horas y nada."]],
           opts: [{ t: "«Diez horas, y la misma paga.»", go: "diez" },
                  { t: "«Que los obreros elijan la canción.»", go: "elegir" },
                  { t: "«Tiene razón. Que sigan.»", go: "razon" }] },
      diez: { say: [["azufre", "¿Diez? ¿Con la misma paga? Eso sale de mis ganancias."],
                    [null, "Discuten una hora. Al final, Azufre hace números en un papel. Los mira. Gruñe."],
                    ["azufre", "Diez. Por un año, a ver qué pasa. Si el Cráter pasa hambre, lo voy a buscar al Vado con la cuenta."]], end: { xp: 18, flag: "e7_diezHoras" } },
      elegir: { say: [[null, "Azufre acepta que los obreros voten qué canción suena en la Forja. Eligen una lenta, de las Mareas, con burbujas. Con esa trabajan mal."],
                      ["azufre", "Producen la mitad. Están felices. El Gremio va a perder plata. No sé si me importa tanto como debería."]], end: { xp: 14, flag: "e7_obrerosEligen" } },
      razon: { say: [["azufre", "Gracias. No lo dice nadie. Lo piensan todos."],
                     [null, "Firma el contrato. La caja nueva se lleva a la Forja esa misma tarde. Suena más fuerte que la otra."]], end: { xp: 6, flag: "e7_gremioCaja" } },
    } },

    "e7-huelgacantada": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { martinete: "Martinete, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la plaza del Cráter, los obreros quieren hacer huelga. Pero cuando suena la canción de trabajo, se les van las ganas. Las piernas solas los llevan a la Forja."],
                 ["martinete", "Quieren comprarle al Coro una canción de huelga. Una que los haga parar. El Coro dice que sí. El problema es que el Gremio ya le compró al Coro otra que los hace volver. Las dos van a sonar a la vez."],
                 ["martinete", "El Coro les vende a los dos lados. Y gana dos veces. Yo soy capataz. Tendría que estar con el Gremio. No sé con quién estoy."]],
           opts: [{ t: "«Hagan la huelga sin canción. Con las manos.»", go: "manos", cNeed: "e7_manosAprendidas" },
                  { t: "«Taparse los oídos con musgo y parar.»", go: "musgo" },
                  { t: "«Que compren la canción de huelga.»", go: "comprar" }] },
      manos: { say: [[null, "Les enseñas a los obreros el gesto de Arpegia: «prometo», la mano en el pecho. Lo hacen frente a frente, en la plaza. Sin sonido."],
                     [null, "Cuando suena la canción de trabajo, las piernas quieren ir. Pero se miran y se acuerdan de la mano en el pecho. Se quedan. Tiemblan. Se quedan."],
                     ["martinete", "Lo prometieron sin ruido. La canción no lo puede tapar. Primera huelga del Claro que no se oye. El Gremio no sabe qué hacer: no hay nada que contestar."]], end: { xp: 22, flag: "e7_huelgaManos" } },
      musgo: { say: [[null, "Compran musgo a Musguito, todo lo que tiene. Se lo meten en los oídos y se sientan en la plaza. No oyen nada. Ni la canción. Ni a Martinete."],
                     ["martinete", "Pararon. Tres días. Ganaron una hora menos por día. Pero ahora no se oyen entre ellos. Discuten con señas y se pelean más."]], end: { xp: 16, flag: "e7_huelgaMusgo" } },
      comprar: { say: [[null, "Compran la canción de huelga. Suenan las dos canciones a la vez en el Cráter: una que dice «paren», otra que dice «vuelvan»."],
                       [null, "Los obreros dan dos pasos hacia la Forja, dos hacia la plaza. Así todo el día. En la noche están agotados y no hicieron nada."],
                       ["martinete", "El Coro cobró de los dos lados. Nosotros no ganamos nada. Bueno, sí: aprendimos que las canciones no son de los que las compran."]], end: { xp: 10, flag: "e7_huelgaDoble" } },
    } },

    "e7-sordos": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { martinete: "Martinete, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En la puerta de la Forja hay seis obreros viejos con sus herramientas en un saco. Son sordos: años de martillo les quitaron el oído. La canción de trabajo no les hace nada."],
                 ["martinete", "Trabajan ocho horas. Los otros, catorce. El Gremio dice que son lentos. Que no rinden. Los echaron esta mañana."],
                 [null, "Uno de los viejos mueve las manos. Otro le contesta igual. Hablan entre ellos con señas, rápidas, viejas, que nadie más entiende."]],
           opts: [{ t: "Saludarlos con el gesto de Arpegia", go: "arpegia", cNeed: "e7_manosAprendidas" },
                  { t: "«Ellos trabajan lo justo. Los otros, de más. Que vuelvan.»", go: "volver" },
                  { t: "Llevarlos con Arpegia, a la cumbre", go: "cumbre" }] },
      arpegia: { say: [[null, "Haces el gesto: la mano abierta en el pecho. Los seis viejos se quedan quietos. Uno sonríe y te contesta con otro gesto, que no conoces."],
                       [null, "Hablan con las manos más que con la boca desde hace treinta años. Tienen palabras para «yunque», «calor», «cansado», «injusto». Arpegia tiene otras. Se parecen."],
                       ["martinete", "Hay más gente que habla así de la que pensaba. Nunca les miré las manos."]], back: "a" },
      volver: { say: [[null, "Vas con Martinete a la oficina del Gremio. Le muestras a Azufre las cuentas: los sordos hacen menos piezas, pero ninguna sale mal. Los otros, cansados, rompen una de cada cinco."],
                      ["martinete", "Volvieron. El Gremio no lo dice, pero sabe que el que trabaja ocho horas trabaja mejor. Lo que no sé es qué hacer con los catorce."]], end: { xp: 18, flag: "e7_sordosVuelven" } },
      cumbre: { say: [[null, "Suben a los Altos. Arpegia los recibe en el mirador. Mueve las manos. Los viejos contestan. Tardan un rato en entenderse. Después no paran."],
                      [null, "A la semana, los seis viejos y Arpegia tienen un idioma de manos que mezcla los dos. Le enseñan a quien quiera. Los primeros en aprender son los chicos de los obreros."],
                      ["martinete", "Los echaron del Cráter y armaron un idioma. Eso no lo produce ninguna canción de trabajo."]], end: { xp: 20, flag: "e7_sordosCumbre" } },
    } },

    "e7-astilla": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { astilla: "Astilla, aprendiz de la Forja" }, start: "a", nodes: {
      a: { say: [[null, "En un rincón de la Forja, una niña de diez años pule clavos al compás de la canción. Tiene las manos llenas de ampollas. Tararea. Sonríe."],
                 ["astilla", "Astilla. Aprendiz. Llevo doce horas. No estoy cansada. Bueno, sí. Pero no lo siento. La canción no me deja sentirlo. Es lindo."],
                 [null, "Se le cae un clavo. Lo levanta sin parar de tararear. Se le cae otro. Le tiemblan los dedos."]],
           opts: [{ t: "Llevarla afuera, lejos de la canción", go: "afuera" },
                  { t: "«¿Tu familia sabe cuántas horas trabajas?»", go: "familia" },
                  { t: "Dejarla trabajar", go: "dejar" }] },
      afuera: { say: [[null, "La sacas de la mano. En la puerta de la Forja, lejos de la caja, Astilla deja de tararear. Se mira las manos. Se sienta en el suelo de golpe."],
                      ["astilla", "Me duele. Todo. Las manos, la espalda, los ojos. ¿Me dolía todo el tiempo? No me di cuenta."],
                      [null, "Llora un rato. Después se duerme ahí mismo, en la piedra tibia. Martinete la tapa con su chaqueta y no dice nada."]], end: { xp: 16, flag: "e7_astillaAfuera" } },
      familia: { say: [["astilla", "Mi mamá trabaja catorce. Mi papá, también. Yo doce porque soy chica. Cuando sea grande, catorce."],
                       [null, "Lo dice contenta, como quien cuenta que va a crecer. Sigue puliendo."]], end: { xp: 10, flag: "e7_astillaSigue" } },
      dejar: { say: [[null, "Astilla sigue puliendo. Tararea. Al final del turno, se desmaya sobre la mesa de clavos. Alguien la lleva a su casa. Al día siguiente vuelve, tarareando."]], end: { xp: 4, flag: "e7_astillaDesmaya" } },
    } },

    "e7-campana": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { azufre: "Azufre, maestro del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "En el patio del Gremio, el maestro tiene una campana nueva, enorme, de metal oscuro, todavía caliente. Los herreros la miran con miedo."],
                 ["azufre", "Azufre, maestro. Una campana para tapar las canciones de los otros. Cuando suene, nadie en el Cráter va a oír otra cosa que la canción del Gremio. Ni la de huelga. Ni la de las Mareas. Nada."],
                 ["azufre", "Los viejos del Fondo dicen que hace mucho alguien hizo campanas para dormir a la Raíz. Esta no es para eso. Esta es para despertar a los obreros."]],
           opts: [{ t: "«Las campanas atadas del Fondo dormían a la Raíz, y la gente olvidaba su nombre.»", go: "fondo", cNeed: "e6_campanasSueno" },
                  { t: "«Si suena, que sea para avisar el fin del turno.»", go: "turno" },
                  { t: "Romperle la lengua a la campana", go: "romper" },
                  { t: "«Que suene.»", go: "sonar" }] },
      fondo: { say: [["azufre", "¿Olvidaban su nombre? Por una campana."],
                     [null, "Mira la campana mucho rato. Le pone la mano encima. Todavía quema."],
                     ["azufre", "Esta es de otro metal. Pero el metal no sabe para qué lo hacen. Eso me lo enseñó Crisol, de chico. No me acordaba."]], back: "a" },
      turno: { say: [[null, "Azufre lo piensa. Esa tarde cuelga la campana en la torre del Gremio. Suena una vez, a las diez horas de trabajo. Fuerte. Tapa todas las canciones."],
                     [null, "En la Forja, los martillos se detienen. Los obreros se miran. Por un momento no suena nada más que la campana."],
                     ["azufre", "Fin del turno. Una campana que hace parar. Es lo contrario de lo que quería. Funciona mejor."]], end: { xp: 20, flag: "e7_campanaTurno" } },
      romper: { say: [[null, "De noche, con un martillo, rompes la lengua de la campana. Queda muda, colgando en el patio."],
                      [null, "En la mañana, Azufre la encuentra. No grita. Le pega con los nudillos. Suena un ruido sordo, de olla."],
                      ["azufre", "Una campana muda. La voy a dejar colgada. Que la vean los herreros. Así se acuerdan de que alguien no quiso."]], end: { xp: 14, flag: "e7_campanaMuda" } },
      sonar: { say: [[null, "La campana suena al mediodía. El Cráter entero se queda quieto un segundo. Después, todos tararean la canción del Gremio, más fuerte que nunca."],
                     [null, "Esa noche, en el Fondo, los soñadores sueñan con campanas. No saben por qué."]], end: { xp: 6, flag: "e7_campanaGremio" } },
    } },

    "e7-cuentas": { kind: "dialogo", need: { era: 7, layer: 2 }, who: { martinete: "Martinete, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "Martinete te muestra el libro de horas de la Forja, a escondidas, en la cocina de su casa. Las columnas suben mes a mes: diez, once, doce, catorce."],
                 ["martinete", "Y la paga es la misma desde el primer mes. Producen el doble. Ganan igual. El doble se lo lleva el Gremio. Y el Coro, por la caja."],
                 ["martinete", "Si muestro esto, me echan. Si no lo muestro, sigo firmando. ¿Qué hago con un libro así?"]],
           opts: [{ t: "«Muéstreselo a los obreros.»", go: "obreros" },
                  { t: "«Cópielo en la pared de la Hondura, para que quede.»", go: "hondura" },
                  { t: "«Guárdelo. Algún día va a servir.»", go: "guardar" }] },
      obreros: { say: [[null, "Martinete lee el libro en la plaza del Cráter, a la hora de la comida. Mes por mes. Los obreros escuchan con el pan en la mano."],
                       [null, "Al día siguiente, nadie entra a la Forja antes de la hora. Nadie se queda después. La canción suena igual. Ellos se tapan los oídos con las manos y se van."],
                       ["martinete", "Me echaron. Me van a contratar de nuevo en un mes: no hay otro que sepa llevar las cuentas. Y ahora las llevo en voz alta."]], end: { xp: 20, flag: "e7_cuentasLeidas" } },
      hondura: { say: [[null, "Bajas el libro a las Cuevas. Cuarcita copia las columnas en una pared nueva, al lado de la lista de leña del invierno."],
                       ["martinete", "Ahí quedó. Al lado de lo de la leña. Mismo tipo de cuenta, otro siglo. Alguien va a ver las dos juntas y va a entender."]], end: { xp: 16, flag: "e7_cuentasPared" } },
      guardar: { say: [["martinete", "Algún día. Sí. Es lo que decía mi abuelo de todo."],
                       [null, "Mete el libro debajo de una tabla del piso. Sigue firmando las horas. Cada noche, antes de dormir, levanta la tabla y lo mira."]], end: { xp: 8, flag: "e7_cuentasGuardadas" } },
    } },

    "e7-hornaza": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { hornaza: "Hornaza, la obrera más vieja" }, start: "a", nodes: {
      a: { say: [[null, "Junto a un horno apagado, una mujer de ochenta años con los brazos llenos de cicatrices de chispas mira la Forja a lo lejos. No tararea nada."],
                 ["hornaza", "Hornaza. Trabajé setenta años en la Forja. Me acuerdo de antes de las canciones. Se martillaba al ritmo del corazón de cada uno. Cada yunque sonaba distinto. Era un ruido horrible y lindo."],
                 ["hornaza", "Ahora todos martillan igual. El mismo golpe, la misma hora. Suena como una sola máquina. Ya no sé cuál es el yunque de mi nieto."]],
           opts: [{ t: "«¿Cómo era el ritmo de antes?»", go: "ritmo", once: true },
                  { t: "Pedirle que enseñe a martillar sin canción", go: "ensenar" },
                  { t: "Llevarla a la Forja a que la oigan", go: "forja" },
                  { t: "«Ya pasó. Ahora es así.»", go: "paso" }] },
      ritmo: { say: [["hornaza", "Cada uno el suyo. Yo martillaba de tres en tres, con una pausa. Mi marido, de dos en dos. Cuando martillábamos juntos, sonaba como si discutiéramos. Discutíamos, también."],
                     ["hornaza", "En el invierno largo, mi abuela decía que se martillaba despacio para no gastar fuerza. En el de los clavos, rápido. Cada época tenía su ritmo. Esta tiene el del Coro."]], back: "a" },
      ensenar: { say: [[null, "Hornaza junta a los aprendices una tarde, en el horno apagado. Les da un martillo a cada uno. Les dice que busquen su propio golpe, sin canción."],
                       [null, "Al principio martillan todos igual, por costumbre. Después uno se equivoca. Otro se ríe. Poco a poco, cada uno encuentra el suyo. Suena horrible."],
                       ["hornaza", "Ahí está. Así sonaba. Ahora cada uno sabe cuál es su yunque. Aunque mañana vuelvan a la canción, ya lo saben."]], end: { xp: 20, flag: "e7_hornazaEnsena" } },
      forja: { say: [[null, "Llevas a Hornaza a la Forja. Ella se para en el medio, con su martillo viejo, y golpea un yunque a su ritmo: de tres en tres, con una pausa. Contra la canción."],
                     [null, "Los obreros la miran. Algunos se equivocan de golpe. Uno, su nieto, la sigue. Después otro. Por un rato, hay dos ritmos en la Forja."],
                     ["hornaza", "Me siguió. Mi nieto. Ahora sé cuál es su yunque: el que se equivocó primero."]], end: { xp: 18, flag: "e7_hornazaForja" } },
      paso: { say: [["hornaza", "Pasó. Sí. Todo pasa. Yo también voy a pasar pronto."],
                    [null, "Se queda mirando la Forja. Cuando te vas, la oyes golpear el horno apagado con los nudillos, de tres en tres, con una pausa."]], end: { xp: 6, flag: "e7_hornazaSola" } },
    } },

    "e7-yunque": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { martinete: "Martinete, capataz del Gremio" }, start: "a", nodes: {
      a: { say: [[null, "Los obreros del Cráter tuvieron una idea: grabar en el viento el sonido de los yunques, de todos, mezclados. Una canción del Fuego, hecha por ellos. Que la oiga todo el Claro."],
                 ["martinete", "Quieren llevarla a los molinos. Que se pegue. Que todo el Claro sepa cómo suena el Cráter. Es nuestra. No la compramos."],
                 ["martinete", "Pero si se pega, en las Cuevas, en el Lago, en el Prado van a martillar sin martillo. Nuestra canción les va a hacer a ellos lo que la del Gremio nos hizo a nosotros."]],
           opts: [{ t: "«Llévenla a los molinos.»", go: "molino" },
                  { t: "«Tóquenla aquí. Que venga a oírla el que quiera.»", go: "aqui" },
                  { t: "«Que la oigan solo una vez, en el Corazón.»", go: "corazon" }] },
      molino: { say: [[null, "La llevan a la cumbre. Aspa la carga en un molino. Al día siguiente, todo el Claro oye el Cráter: golpes, chispas, gritos de capataz."],
                      [null, "En el Lago, la gente de las Mareas golpea las barcas sin saber por qué. En el Prado, los panaderos amasan a golpes. Se cansan."],
                      ["martinete", "Ahora somos el Coro. Hicimos lo mismo. Con orgullo, encima. No sé si es peor o mejor."]], end: { xp: 10, flag: "e7_fuegoMolino" } },
      aqui: { say: [[null, "Arman una noche en la plaza del Cráter. Los obreros tocan los yunques, cada uno a su ritmo, sin canción. Viene gente de otros pueblos a escuchar. No se les pega. Se lo llevan en la memoria, no en la cabeza."],
                    ["martinete", "El que quiere, viene. El que no, no. Así era la música antes de los molinos, dice Hornaza. Cuesta más. Vale más."]], end: { xp: 20, flag: "e7_fuegoPlaza" } },
      corazon: { say: [[null, "Llevan los yunques al Corazón en carretas. Una tarde los tocan frente a las estatuas, todos a la vez, una sola vez."],
                       [null, "La Raíz, abajo, se mueve. La nota del talón cambia un momento, como si contestara. Después vuelve a la de siempre."],
                       ["martinete", "Le tocamos a la Raíz. No a la gente. Y la Raíz contestó. Eso no lo compra el Coro."]], end: { xp: 18, flag: "e7_fuegoCorazon" } },
    } },
  });

  /* ---------- Bosque Hondo: los pájaros, el musgo, el Concejo de los setos, las raíces que beben, las hojas que traen palabras, el Largo Silencio, la leñadora y el roble que repite ---------- */
  add("forest", {
    "e7-calandria": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { calandria: "Calandria, la de los pájaros" }, start: "a", nodes: {
      a: { say: [[null, "Detrás de los setos, en un claro del Bosque, una niña de doce años tiene jaulas de mimbre colgadas de las ramas. Adentro hay pájaros quietos, mudos."],
                 ["calandria", "Calandria. Cuido los pájaros que quedan. Desde los setos, no cantan. El viento no entra y ellos no saben qué cantar. Antes aprendían del viento, dice mi abuela."],
                 ["calandria", "Afuera de los setos, los pájaros cantan las canciones del Coro. Los oí. Un mirlo cantaba «las Casas que alumbran». Es horrible. Prefiero los míos mudos."]],
           opts: [{ t: "Llevar las jaulas al hueco del seto", go: "hueco", cNeed: "e7_setoHueco" },
                  { t: "Enseñarles la nana a los pájaros", go: "nana" },
                  { t: "«Suéltalos afuera. Que canten lo que quieran.»", go: "soltar" }] },
      hueco: { say: [[null, "Cuelgan las jaulas frente al hueco que se abrió en el seto. Entra un poco de viento, un pedazo de canción, ruido de hojas."],
                     [null, "Al tercer día, un pájaro canta. No es la canción del Coro. Es un pedazo, mezclado con su propio silbido. Algo nuevo."],
                     ["calandria", "Eligió. Agarró un poco de afuera y lo mezcló con lo suyo. Eso es cantar, ¿no? Lo demás es repetir."]], end: { xp: 20, flag: "e7_pajarosEligen" } },
      nana: { say: [[null, "Te sientas con Calandria frente a las jaulas y le cantan la nana a los pájaros. Una vez. Diez. Cien. Dos días."],
                    [null, "Un pájaro gris la repite. Mal, a pedazos, pero la repite. Después otro. A la semana, el claro de Calandria canta la nana."],
                    ["calandria", "Ahora el Bosque canta la nana. No la compró nadie. La aprendieron de nosotros. Mi abuela va a llorar."]], end: { xp: 18, flag: "e7_pajarosNana" } },
      soltar: { say: [[null, "Calandria abre las jaulas del otro lado del seto. Los pájaros salen volando. Al rato, desde los árboles de afuera, se oye la canción de la semana, silbada."],
                      ["calandria", "Están libres. Y cantan lo del Coro. Libres para eso."]], end: { xp: 8, flag: "e7_pajarosSueltos" } },
    } },

    "e7-musgobosque": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { ligustro: "Ligustro, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En la entrada del Bosque, Ligustro reparte musgo para los oídos a todos los que entran. Es obligatorio. Lo dice un cartel nuevo del Concejo."],
                 ["ligustro", "Si alguien entra con una canción pegada, la canta adentro, y la canción se queda en el Bosque. Ya pasó. Una niña entró cantando y en una semana medio Bosque cantaba lo mismo."],
                 ["ligustro", "Musgo en los oídos al entrar, hasta que se te pase. Así se protege el Bosque. Así se protegía en el Largo Silencio."]],
           opts: [{ t: "«En el Largo Silencio el musgo era para no oír. Acebo se lo sacó para escuchar.»", go: "acebo", cNeed: "e6_silencioAbierto" },
                  { t: "Entrar sin musgo", go: "sin" },
                  { t: "Ponerte el musgo y entrar", go: "con" }] },
      acebo: { say: [["ligustro", "Acebo. Mi bisabuela. Sí. Se lo sacó y dijo que la Raíz hablaba más bajo si alguien la escuchaba."],
                     ["ligustro", "Pero ella no tenía canciones del Coro en el viento. Tenía a la Raíz. Lo de ahora es otra cosa. Creo. No sé."]], back: "a" },
      sin: { say: [[null, "Entras sin musgo. Ligustro protesta, pero no te detiene. Adentro, la canción de la semana te sale sola, bajito, mientras caminas."],
                   [null, "Un chico del Bosque la oye. La repite. Ligustro corre detrás de él con un puñado de musgo."],
                   ["ligustro", "¿Ve? Uno. Eso pasa. ¿Quién la cura ahora? No se cura. Se espera a que el Coro venda otra."]], end: { xp: 8, flag: "e7_bosqueContagio" } },
      con: { say: [[null, "Te pones el musgo. El Bosque se vuelve un silencio verde, de algodón. Caminas una hora. La canción se te va de la cabeza poco a poco."],
                   [null, "Cuando te lo sacas, en el centro del Bosque, oyes por primera vez algo que no es canción: el agua, una rama, tu respiración."],
                   ["ligustro", "Eso. Eso queríamos guardar. No el silencio: lo que hay debajo."]], end: { xp: 16, flag: "e7_bosqueMusgo" } },
    } },

    "e7-concejo": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { ligustro: "Ligustro, del Concejo del Musgo", zorzal: "Zorzal, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En la sala del Concejo del Musgo se discute la altura de los setos. Ligustro quiere más altos. Un concejal joven, de barba rala, quiere bajarlos."],
                 ["zorzal", "Zorzal, del Concejo. Los setos nos están dejando sordos. No vendemos al Prado. No compramos en el Cráter. Los chicos no saben qué pasa afuera. El Bosque se está quedando solo."],
                 ["ligustro", "Solo y entero. Afuera se compran las cabezas por canciones. Prefiero un Bosque solo a un Bosque comprado."]],
           opts: [{ t: "«Que los setos tengan puertas, y cada uno elija.»", go: "puertas" },
                  { t: "Apoyar a Ligustro", go: "ligustro" },
                  { t: "Apoyar a Zorzal", go: "zorzal" }] },
      puertas: { say: [[null, "Proponen puertas de madera en los setos, cada cien pasos. Abiertas de día, cerradas de noche. El que quiere, sale. El que vuelve, pasa por el musgo."],
                       ["zorzal", "Puertas. Se puede ir y volver. Me parece poco. Me parece bien."],
                       ["ligustro", "Puertas. Por ahí va a entrar todo. Despacio, pero todo. Lo voto igual. Mejor despacio que de golpe."]], end: { xp: 20, flag: "e7_setosPuertas" } },
      ligustro: { say: [[null, "El Concejo vota con Ligustro. Los setos crecen un metro más. Zorzal se va de la sala sin saludar."],
                        [null, "A la semana, Zorzal y cinco familias jóvenes se mudan al otro lado de los setos. Esa noche, desde afuera, se los oye cantar la canción del Coro."]], end: { xp: 10, flag: "e7_bosqueParte" } },
      zorzal: { say: [[null, "El Concejo vota con Zorzal. Bajan los setos a la altura de una persona. El viento pasa por arriba. Las canciones también."],
                      ["ligustro", "Ya está. Nos van a cantar las cabezas. A los chicos primero."],
                      ["zorzal", "Sí. Y van a saber qué pasa afuera. Y van a tener que elegir. Como todos."]], end: { xp: 14, flag: "e7_setosBajos" } },
    } },

    "e7-raices": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { ligustro: "Ligustro, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "Al pie de los setos, la tierra está seca y negra. Los árboles viejos que están cerca tienen las hojas amarillas. Ligustro cava con las manos."],
                 ["ligustro", "Las raíces de los setos. Bajan hondo. Muy hondo. Llegan a las raíces de la Raíz. Le beben la savia. Por eso crecen tan rápido. Por eso los árboles de al lado se mueren."],
                 [null, "De la tierra removida sube un olor raro. Dulce. Como la savia negra de las historias viejas."]],
           opts: [{ t: "Cortar las raíces más hondas de los setos", go: "cortar" },
                  { t: "«Arranquen los setos de esta parte.»", go: "arrancar" },
                  { t: "«Si los setos protegen, el costo vale.»", go: "dejar" }] },
      cortar: { say: [[null, "Pasan una semana cortando raíces con hachas cortas, de rodillas en la tierra negra. Los setos se secan un poco. No caen."],
                      [null, "Los árboles viejos de al lado sacan hojas nuevas al mes. Chicas, verdes."],
                      ["ligustro", "Los setos siguen. Más bajos, más flacos. Pero ya no le chupan a la Raíz. No sabía que proteger costaba eso."]], end: { xp: 18, flag: "e7_raicesCortadas" } },
      arrancar: { say: [[null, "Arrancan los setos de ese lado del Bosque. Queda una franja abierta. El viento entra por ahí, con sus canciones. Los árboles viejos respiran."],
                        ["ligustro", "Un lado abierto. Para que viva el Bosque, hay que dejar entrar lo que no queremos. Eso no lo dice ningún libro del Concejo."]], end: { xp: 16, flag: "e7_setosAbiertos" } },
      dejar: { say: [["ligustro", "El costo. Sí. Unos árboles."],
                     [null, "Los setos siguen creciendo. Al año, hay un claro nuevo en el Bosque, donde había robles. Los setos lo rodean."]], end: { xp: 6, flag: "e7_raicesBeben" } },
    } },

    "e7-hojas": { kind: "encuentro", need: { era: 7, layer: 2 }, who: { zorzal: "Zorzal, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "Por encima de los setos, el viento trae hojas que no son del Bosque. Tienen palabras escritas a mano: pedazos de canciones, nombres, «ven al Prado», «el Coro es de todos»."],
                 ["zorzal", "Zorzal, del Concejo. El Coro las tira desde los molinos. Si no pueden entrar las canciones, entran las letras. Los chicos las juntan. Las leen en voz alta. Y cuando las leen, se les pegan igual."],
                 ["zorzal", "Ligustro quiere quemarlas todas. Yo creo que hay que leerlas. Saber qué dicen."]],
           opts: [{ t: "Leerlas en voz alta con los chicos, y discutir cada una", go: "leer" },
                  { t: "Quemarlas", go: "quemar" },
                  { t: "Escribir en el revés de cada hoja una respuesta y devolverlas al viento", go: "responder" }] },
      leer: { say: [[null, "Te sientas con los chicos del Bosque y Zorzal. Lees una hoja. Discuten si es verdad. Una dice que el viento es del Coro. Un chico pregunta quién le vendió el viento al Coro."],
                    [null, "Nadie sabe. Leen otra. Y otra. Al final de la tarde, los chicos tienen preguntas, no canciones."],
                    ["zorzal", "Así se lee. Con preguntas. Las palabras pegadas se despegan cuando alguien les pregunta algo."]], end: { xp: 20, flag: "e7_hojasLeidas" } },
      quemar: { say: [[null, "Juntan las hojas en una pila y las queman. El humo sube por encima de los setos. Huele a tinta."],
                      ["zorzal", "Ya no están. Mañana caen otras. Ligustro va a quemar todas las mañanas. Algún día se va a cansar."]], end: { xp: 8, flag: "e7_hojasQuemadas" } },
      responder: { say: [[null, "En el revés de cada hoja, los chicos escriben lo que piensan. «¿Quién le vendió el viento?». «Aquí cantan los pájaros». «No queremos tu canción». Las tiran al viento desde el árbol más alto."],
                         [null, "A la semana, en la cumbre, Aspa encuentra hojas escritas por los dos lados enganchadas en las aspas. Las lee. Las guarda en un cajón."],
                         ["zorzal", "Ahora el viento lleva dos cosas. Lo de ellos y lo nuestro. Es la primera vez que le contestamos al Coro."]], end: { xp: 18, flag: "e7_hojasRespuesta" } },
    } },

    "e7-silencio": { kind: "dialogo", need: { era: 7, layer: 3 }, who: { ligustro: "Ligustro, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "Es el Largo Silencio. Todo el Bosque calla un día entero. Con los setos, el silencio es total. Ni el viento. Ni un pájaro. Ligustro está sentado contra el roble más viejo, con los ojos cerrados."],
                 ["ligustro", "Mi bisabuela oía a la Raíz en este día. Decía que habla más bajo si alguien escucha. Yo nunca la oí. Con los setos, menos. No entra nada. Ni sale."],
                 ["ligustro", "Quizás la Raíz habla por el viento. Y el viento no pasa. Quizás la tapé con mis propios setos."]],
           opts: [{ t: "Llevarlo al hueco del seto a escuchar", go: "hueco", cNeed: "e7_setoHueco" },
                  { t: "Sentarte con él contra el roble y escuchar la tierra", go: "tierra" },
                  { t: "«Si no se oye, no se oye. Descanse.»", go: "descanso" }] },
      hueco: { say: [[null, "Llevas a Ligustro al hueco del seto. Se sienta frente al hueco, en silencio. Pasa el viento. Trae un pedazo de canción del Coro. Y, debajo, otra cosa."],
                     [null, "Una nota larga, baja, que no cambia. La del talón de la Raíz, que llega hasta aquí por debajo de todo."],
                     ["ligustro", "La oí. Por el hueco. La Raíz habla con el mismo viento que el Coro vende. Para oírla hay que dejar entrar lo otro. No hay forma de elegir solo lo bueno."]], end: { xp: 22, flag: "e7_silencioRaiz" } },
      tierra: { say: [[null, "Te sientas a su lado, con la espalda en el roble. Ponen las manos en la tierra. Pasa una hora. Dos."],
                      [null, "Al final sientes algo: un latido muy lento, en la tierra, bajo las manos. No es sonido. Es como la mano abierta de Arpegia en el pecho."],
                      ["ligustro", "No se oye. Se siente. Mi bisabuela la oía con los oídos. Yo con las manos. Algo cambió en la Raíz. O en nosotros."]], end: { xp: 20, flag: "e7_silencioManos" } },
      descanso: { say: [["ligustro", "Descansar. Sí. Es lo único que el silencio sabe hacer ahora."],
                        [null, "Ligustro se duerme contra el roble. Cuando el Largo Silencio termina, se despierta y no oyó nada. Vuelve al Concejo a votar más setos."]], end: { xp: 6, flag: "e7_silencioSordo" } },
    } },

    "e7-hachuela": { kind: "encuentro", need: { era: 7, layer: 1 }, who: { hachuela: "Hachuela, leñadora" }, start: "a", nodes: {
      a: { say: [[null, "En el borde del Bosque, afuera de los setos, una mujer corpulenta corta un roble con un hacha doble. Al lado, una carreta del Coro espera con un carretero dormido."],
                 ["hachuela", "Hachuela, leñadora. El Coro necesita madera para molinos nuevos. Paga bien. Los robles del Bosque son los mejores: viejos, derechos, duros. El Concejo dice que no. Pero estos están afuera de los setos. No son de nadie."],
                 ["hachuela", "Tengo cuatro hijos y el Bosque no me compra nada desde que puso los setos. ¿De qué vivo?"]],
           opts: [{ t: "«Que el Concejo le pague por cuidar los robles en lugar de cortarlos.»", go: "concejo" },
                  { t: "«Corte, pero plante dos por cada uno.»", go: "plantar" },
                  { t: "«Venda. Es su madera.»", go: "vender" }] },
      concejo: { say: [[null, "Vas al Concejo con Hachuela. Discuten. Ligustro dice que no hay plata. Zorzal dice que hay plata para setos y no para robles."],
                       [null, "Al final le pagan a Hachuela la mitad de lo que paga el Coro, por cuidar los robles de afuera. Ella acepta, de mala gana."],
                       ["hachuela", "La mitad. Por no cortar. Me cuesta entenderlo. Mis hijos van a comer menos. Los robles van a vivir más que mis hijos. Eso sí lo entiendo."]], end: { xp: 18, flag: "e7_hachuelaCuida" } },
      plantar: { say: [["hachuela", "¿Dos por uno? Tardan cien años en crecer."],
                       [null, "Lo hace igual. Por cada roble que corta, planta dos bellotas. Sus hijos la ayudan. Les enseña a cuál regar primero."],
                       ["hachuela", "Mis tataranietos van a tener robles. El Coro, molinos. Algún día el Coro se va a terminar. Los robles, no."]], end: { xp: 16, flag: "e7_hachuelaPlanta" } },
      vender: { say: [["hachuela", "Mi madera. Eso digo yo."],
                      [null, "Corta seis robles esa semana. La carreta del Coro se va cargada hacia los Altos. Al mes, hay dos molinos nuevos en la cumbre."]], end: { xp: 6, flag: "e7_hachuelaVende" } },
    } },

    "e7-robleeco": { kind: "encuentro", need: { era: 7, layer: 3 }, who: { zorzal: "Zorzal, del Concejo del Musgo" }, start: "a", nodes: {
      a: { say: [[null, "En el medio del Bosque está el roble del hueco, el que repetía voces. Ahora, aunque hay setos, repite canciones. Las del Coro. Las de la semana. Muy bajito, desde el hueco."],
                 ["zorzal", "Zorzal, del Concejo. No sabemos cómo le llegan. Por las raíces, creo. El viento entra a la tierra del otro lado de los setos y sale aquí, por el roble."],
                 ["zorzal", "Ligustro quiere cortarlo. Dice que es una puerta que no se puede cerrar."]],
           opts: [{ t: "«Lo salvaron una vez. Que no lo corten.»", go: "salvado", cNeed: "e6_robleSalvado" },
                  { t: "Meter la cabeza en el hueco y escuchar qué repite de verdad", go: "escuchar" },
                  { t: "«Que lo corten.»", go: "cortar" },
                  { t: "Cantarle algo tuyo al hueco", go: "cantar" }] },
      salvado: { say: [["zorzal", "Mi abuelo me contó. Que alguien de afuera habló con el Concejo y el roble se quedó. Que repetía lo de una familia que vivió adentro, en el invierno."],
                       ["zorzal", "Ahora repite lo del Coro. Pero sigue siendo el mismo árbol. No es culpa suya lo que le llega."]], back: "a" },
      escuchar: { say: [[null, "Metes la cabeza en el hueco. Huele a madera húmeda. Las canciones del Coro suenan bajito. Pero debajo, más bajo, hay otras voces: una familia, un niño que pide pan, una mujer que canta la nana en el frío."],
                        [null, "El roble no cambió de memoria. Le pusieron encima canciones nuevas, pero las viejas siguen ahí, abajo, como capas de corteza."],
                        ["zorzal", "Las dos cosas. Lo del Coro y lo de antes. Si lo cortamos, perdemos las dos."]], end: { xp: 20, flag: "e7_robleCapas" } },
      cortar: { say: [[null, "El Concejo corta el roble. Tarda un día entero: es enorme. Cuando cae, el hueco se abre en dos. Sale un suspiro, largo, de muchas voces."],
                      ["zorzal", "Ya no repite. Ni lo del Coro, ni lo de antes. Ligustro está contento. Yo no puedo mirar el tronco."]], end: { xp: 8, flag: "e7_robleCortado" } },
      cantar: { say: [[null, "Te acercas al hueco y cantas algo tuyo, lo que te sale. El roble se calla un momento. Después lo repite, bajito, con tu voz."],
                      [null, "Al día siguiente, en el Bosque, se oye tu canción saliendo del roble, mezclada con las del Coro. Algunos chicos la aprenden de ahí."],
                      ["zorzal", "Ahora el roble también tiene lo suyo. Lo de usted. Es raro que un árbol cante algo que nadie vendió."]], end: { xp: 16, flag: "e7_robleCanta" } },
    } },
  });
})(window.EVEVENTS);
